import { computed, effect, Injectable, signal } from '@angular/core';
import { Task, TaskFilter } from '../models/task.model';

const STORAGE_KEY = 'angular-todo-app.tasks';

@Injectable({ providedIn: 'root' })
export class TaskStore {
  private readonly _tasks = signal<Task[]>(this.load());
  private readonly _filter = signal<TaskFilter>('all');

  readonly tasks = this._tasks.asReadonly();
  readonly filter = this._filter.asReadonly();

  readonly visibleTasks = computed(() => {
    const filter = this._filter();
    return this._tasks().filter((task) => {
      if (filter === 'active') return !task.completed;
      if (filter === 'completed') return task.completed;
      return true;
    });
  });

  readonly remainingCount = computed(() => this._tasks().filter((t) => !t.completed).length);
  readonly completedCount = computed(() => this._tasks().filter((t) => t.completed).length);
  readonly counts = computed(() => ({
    all: this._tasks().length,
    active: this.remainingCount(),
    completed: this.completedCount(),
  }));

  constructor() {
    effect(() => this.save(this._tasks()));
  }

  add(title: string): void {
    const trimmed = title.trim();
    if (!trimmed) return;
    this._tasks.update((tasks) => [...tasks, this.createTask(trimmed)]);
  }

  toggle(id: string): void {
    this._tasks.update((tasks) => tasks.map(t => t.id === id ? {...t, completed: !t.completed} : t));
  }

  rename(id: string, title: string): void {
    const trimmed = title.trim();
    if (!trimmed) {
      this.remove(id);
      return;
    }
    this._tasks.update(...);
  }

  remove(id: string): void {...}

  setFilter(filter: TaskFilter): void { this._filter.set(filter); }

  private createTask(title: string): Task {
    return { id: crypto.randomUUID(), title, completed: false, createdAt: Date.now() };
  }

  private load(): Task[] {
    try {
      const raw = localStorage.getItem(STORAGE_KEY);
      if (!raw) return [];
      const parsed: unknown = JSON.parse(raw);
      if (!Array.isArray(parsed)) return [];
      return parsed.filter(isTask);
    } catch { return []; }
  }

  private save(tasks: Task[]): void {
    try { localStorage.setItem(STORAGE_KEY, JSON.stringify(tasks)); } catch { /* storage unavailable */ }
  }
}

function isTask(value: unknown): value is Task { ... }
```

