// Browser-safe SHA-256 / HMAC helpers shared by the Meterless engine ports.
// The implementation is dependency-free so the same code runs in Angular,
// Node (conformance runners), and tests.

const K = new Uint32Array([
  0x428a2f98, 0x71374491, 0xb5c0fbcf, 0xe9b5dba5, 0x3956c25b, 0x59f111f1, 0x923f82a4, 0xab1c5ed5,
  0xd807aa98, 0x12835b01, 0x243185be, 0x550c7dc3, 0x72be5d74, 0x80deb1fe, 0x9bdc06a7, 0xc19bf174,
  0xe49b69c1, 0xefbe4786, 0x0fc19dc6, 0x240ca1cc, 0x2de92c6f, 0x4a7484aa, 0x5cb0a9dc, 0x76f988da,
  0x983e5152, 0xa831c66d, 0xb00327c8, 0xbf597fc7, 0xc6e00bf3, 0xd5a79147, 0x06ca6351, 0x14292967,
  0x27b70a85, 0x2e1b2138, 0x4d2c6dfc, 0x53380d13, 0x650a7354, 0x766a0abb, 0x81c2c92e, 0x92722c85,
  0xa2bfe8a1, 0xa81a664b, 0xc24b8b70, 0xc76c51a3, 0xd192e819, 0xd6990624, 0xf40e3585, 0x106aa070,
  0x19a4c116, 0x1e376c08, 0x2748774c, 0x34b0bcb5, 0x391c0cb3, 0x4ed8aa4a, 0x5b9cca4f, 0x682e6ff3,
  0x748f82ee, 0x78a5636f, 0x84c87814, 0x8cc70208, 0x90befffa, 0xa4506ceb, 0xbef9a3f7, 0xc67178f2,
]);

function rotr(x: number, n: number): number {
  return (x >>> n) | (x << (32 - n));
}

export function sha256Bytes(input: Uint8Array): Uint8Array {
  const len = input.length;
  const bitLenHi = Math.floor(len / 0x20000000) >>> 0;
  const bitLenLo = (len << 3) >>> 0;
  const paddedLen = (((len + 8) >> 6) + 1) << 6;
  const padded = new Uint8Array(paddedLen);
  padded.set(input);
  padded[len] = 0x80;

  const dv = new DataView(padded.buffer);
  dv.setUint32(paddedLen - 8, bitLenHi);
  dv.setUint32(paddedLen - 4, bitLenLo);

  let h0 = 0x6a09e667;
  let h1 = 0xbb67ae85;
  let h2 = 0x3c6ef372;
  let h3 = 0xa54ff53a;
  let h4 = 0x510e527f;
  let h5 = 0x9b05688c;
  let h6 = 0x1f83d9ab;
  let h7 = 0x5be0cd19;

  const w = new Uint32Array(64);
  for (let i = 0; i < paddedLen; i += 64) {
    for (let t = 0; t < 16; t++) {
      w[t] = dv.getUint32(i + t * 4);
    }
    for (let t = 16; t < 64; t++) {
      const s0 = rotr(w[t - 15], 7) ^ rotr(w[t - 15], 18) ^ (w[t - 15] >>> 3);
      const s1 = rotr(w[t - 2], 17) ^ rotr(w[t - 2], 19) ^ (w[t - 2] >>> 10);
      w[t] = (w[t - 16] + s0 + w[t - 7] + s1) >>> 0;
    }

    let a = h0;
    let b = h1;
    let c = h2;
    let d = h3;
    let e = h4;
    let f = h5;
    let g = h6;
    let h = h7;

    for (let t = 0; t < 64; t++) {
      const s1 = rotr(e, 6) ^ rotr(e, 11) ^ rotr(e, 25);
      const ch = (e & f) ^ (~e & g);
      const temp1 = (h + s1 + ch + K[t] + w[t]) >>> 0;
      const s0 = rotr(a, 2) ^ rotr(a, 13) ^ rotr(a, 22);
      const maj = (a & b) ^ (a & c) ^ (b & c);
      const temp2 = (s0 + maj) >>> 0;
      h = g;
      g = f;
      f = e;
      e = (d + temp1) >>> 0;
      d = c;
      c = b;
      b = a;
      a = (temp1 + temp2) >>> 0;
    }

    h0 = (h0 + a) >>> 0;
    h1 = (h1 + b) >>> 0;
    h2 = (h2 + c) >>> 0;
    h3 = (h3 + d) >>> 0;
    h4 = (h4 + e) >>> 0;
    h5 = (h5 + f) >>> 0;
    h6 = (h6 + g) >>> 0;
    h7 = (h7 + h) >>> 0;
  }

  const out = new Uint8Array(32);
  const outView = new DataView(out.buffer);
  [h0, h1, h2, h3, h4, h5, h6, h7].forEach((value, index) => {
    outView.setUint32(index * 4, value);
  });
  return out;
}

export function sha256Hex(input: string): string {
  return [...sha256Bytes(new TextEncoder().encode(input))]
    .map((byte) => byte.toString(16).padStart(2, '0'))
    .join('');
}

export function hmacSha256Hex(key: string, message: string): string {
  const blockSize = 64;
  const encoder = new TextEncoder();
  let keyBytes = encoder.encode(key);
  if (keyBytes.length > blockSize) {
    keyBytes = sha256Bytes(keyBytes);
  }

  const inner = new Uint8Array(blockSize + encoder.encode(message).length);
  const outer = new Uint8Array(blockSize + 32);
  for (let i = 0; i < blockSize; i++) {
    const byte = keyBytes[i] ?? 0;
    inner[i] = byte ^ 0x36;
    outer[i] = byte ^ 0x5c;
  }
  inner.set(encoder.encode(message), blockSize);
  outer.set(sha256Bytes(inner), blockSize);

  return [...sha256Bytes(outer)]
    .map((byte) => byte.toString(16).padStart(2, '0'))
    .join('');
}

export function canonicalJson(value: unknown): string {
  if (value === null || typeof value !== 'object') {
    const serialized = JSON.stringify(value);
    return serialized === undefined ? 'null' : serialized;
  }
  if (Array.isArray(value)) {
    return `[${value.map((item) => canonicalJson(item)).join(',')}]`;
  }
  const record = value as Record<string, unknown>;
  const keys = Object.keys(record)
    .filter((key) => record[key] !== undefined)
    .sort();
  return `{${keys
    .map((key) => `${JSON.stringify(key)}:${canonicalJson(record[key])}`)
    .join(',')}}`;
}

// Scout Intent public types. These mirror the AGENTS.md contract while
// staying framework-free so the core can run in the browser and under the
// Node conformance/eval harness.

export type RiskClass = 'low' | 'medium' | 'high';
export type RiskLevel = RiskClass | 'block';
export type ConfidenceBand = 'high' | 'medium' | 'low' | 'reject';

export interface ParameterProperty {
  type?: string;
  enum?: string[];
  minimum?: number;
  maximum?: number;
  items?: { type?: string };
  description?: string;
}

export interface ParameterSchema {
  type?: string;
  properties?: Record<string, ParameterProperty>;
  required?: string[];
}

export interface IntentDefinition {
  id: string;
  category: string;
  description: string;
  parameters: ParameterSchema;
  capabilities: string[];
  riskClass: RiskClass;
  surfaces: string[];
  roles: string[];
  examples: string[];
  version: number;
  /** Optional deterministic Stage-1 triggers, expressed as regular expressions. */
  triggers?: string[];
}

export interface IntentRegistry {
  version: number;
  intents: IntentDefinition[];
}

export interface UserRef {
  id: string;
  role?: string;
}

export interface DecisionInput {
  prompt: string;
  user?: UserRef;
  surface?: string;
  context?: unknown;
}

export interface IntentCandidate {
  intent: string;
  score: number;
  band: ConfidenceBand;
  span?: [number, number];
}

export interface BoundIntent {
  primary: {
    id: string;
    category: string;
    confidence: number;
    band: ConfidenceBand;
    parameters: Record<string, unknown>;
    references: Record<string, unknown>;
  };
  alternates: IntentCandidate[];
}

export interface ApprovalRecord {
  kind: 'user-confirm' | 'operator-review';
  status: 'required' | 'approved' | 'rejected';
  reason: string;
}

export interface RiskAssessment {
  level: RiskLevel;
  flags: string[];
  redactions: string[];
  reason?: string;
  approvals: ApprovalRecord[];
}

export interface ToolStep {
  capability: string;
  tool: string;
  input: Record<string, unknown>;
}

export interface ModelProfileRef {
  id: string;
  provider: 'local' | 'remote';
  model: string;
}

export interface ExecutionScope {
  user: UserRef;
  surface: string;
  capabilities: string[];
  deadline?: string;
  budget?: number;
}

export interface ExecutionContract {
  contractId: string;
  parentId?: string;
  traceId: string;
  intent: BoundIntent;
  risk: RiskAssessment;
  toolPlan: ToolStep[];
  modelProfile: ModelProfileRef;
  scope: ExecutionScope;
  issuedAt: string;
  expiresAt: string;
  registryVersion: number;
  policyPackVersion: string;
  signature: string;
  signedBy: 'scout';
}

export interface ClarificationOption {
  label: string;
  intent?: string;
  prompt?: string;
}

export interface Clarification {
  question: string;
  options: ClarificationOption[];
  trigger: 'low-band' | 'tie' | 'params' | 'high-risk' | 'underspecified' | 'reference-unresolved';
}

export interface Decision {
  prompt: string;
  candidates: IntentCandidate[];
  intent: BoundIntent;
  risk: RiskAssessment;
  toolPlan: ToolStep[];
  clarification?: Clarification;
  executionContract: ExecutionContract;
  secondaryIntents: IntentCandidate[];
  latencyMs: number;
}

export interface ScoutOptions {
  intentRegistry: IntentRegistry;
  policyPack?: string | string[];
  modelProfiles?: unknown;
  signingSecret?: string;
  clock?: () => number;
  /** Optional Stage-2 rescoring hook; Stage 1 stands when absent. */
  semanticScorer?: (prompt: string, intent: IntentDefinition) => number;
}

export interface ClassifyInput {
  prompt: string;
  surface?: string;
}

export interface ReplanInput {
  parent: string;
  reason: string;
  state?: unknown;
}

import type { IntentDefinition, IntentRegistry } from './types';

export function normalizeRegistry(input: IntentRegistry | IntentDefinition[]): IntentRegistry {
  const registry = Array.isArray(input)
    ? { version: 1, intents: input }
    : input;

  if (!registry || !Array.isArray(registry.intents)) {
    throw new Error('Scout: intentRegistry must contain an intents array');
  }

  const seen = new Set<string>();
  for (const intent of registry.intents) {
    if (!intent.id || !/^[a-z0-9]+(?:[.-][a-z0-9]+)*$/i.test(intent.id)) {
      throw new Error(`Scout: invalid intent id "${intent.id}"`);
    }
    if (seen.has(intent.id)) {
      throw new Error(`Scout: duplicate intent id "${intent.id}"`);
    }
    seen.add(intent.id);
    if (!Array.isArray(intent.examples) || intent.examples.length === 0) {
      throw new Error(`Scout: intent "${intent.id}" needs at least one example`);
    }
  }

  return {
    version: registry.version ?? 1,
    intents: registry.intents.map((intent) => ({
      ...intent,
      capabilities: intent.capabilities ?? [],
      surfaces: intent.surfaces ?? ['chat'],
      roles: intent.roles ?? ['*'],
      examples: intent.examples,
      parameters: intent.parameters ?? { type: 'object', properties: {} },
      version: intent.version ?? 1,
    })),
  };
}

export function findIntent(registry: IntentRegistry, id: string): IntentDefinition | undefined {
  return registry.intents.find((intent) => intent.id === id);
}

import type { ConfidenceBand, IntentCandidate, IntentDefinition, IntentRegistry } from './types';

const STOPWORDS = new Set([
  'a', 'an', 'and', 'are', 'as', 'at', 'be', 'but', 'by', 'can', 'could', 'do', 'does', 'for',
  'from', 'give', 'has', 'have', 'i', 'in', 'is', 'it', 'me', 'my', 'of', 'on', 'or', 'our',
  'please', 'show', 'so', 'that', 'the', 'their', 'them', 'this', 'to', 'us', 'was', 'we',
  'what', 'when', 'where', 'which', 'who', 'will', 'with', 'would', 'you', 'your',
]);

export function normalizeText(text: string): string {
  return text
    .normalize('NFKD')
    .replace(/[\u0300-\u036f]/g, '')
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();
}

export function tokenize(text: string): string[] {
  return normalizeText(text)
    .split(' ')
    .filter((token) => token.length > 1 && !STOPWORDS.has(token));
}

export function bandFor(score: number): ConfidenceBand {
  if (score >= 0.8) return 'high';
  if (score >= 0.55) return 'medium';
  if (score >= 0.4) return 'low';
  return 'reject';
}

export function clamp01(value: number): number {
  return Math.min(1, Math.max(0, value));
}

interface IntentProfile {
  intent: IntentDefinition;
  phrases: string[];
  triggers: RegExp[];
  weights: Map<string, number>;
  exampleTokens: Set<string>[];
}

function addWeight(weights: Map<string, number>, token: string, weight: number): void {
  weights.set(token, Math.max(weights.get(token) ?? 0, weight));
}

export function buildProfiles(registry: IntentRegistry): IntentProfile[] {
  return registry.intents.map((intent) => {
    const weights = new Map<string, number>();
    const phrases = intent.examples.map(normalizeText).filter(Boolean);
    const triggers: RegExp[] = [];
    for (const trigger of intent.triggers ?? []) {
      try {
        triggers.push(new RegExp(trigger, 'i'));
      } catch {
        // A bad trigger is a registry bug; validation remains deterministic.
      }
    }

    for (const part of intent.id.split(/[.-]/)) {
      if (part.length > 1) addWeight(weights, part, 3);
    }
    addWeight(weights, intent.category, 1);
    for (const token of tokenize(intent.description)) addWeight(weights, token, 0.7);
    for (const example of intent.examples) {
      for (const token of tokenize(example)) addWeight(weights, token, 1.5);
    }
    for (const trigger of intent.triggers ?? []) {
      for (const token of tokenize(trigger.replace(/[\\^$.*+?()[\]{}|]/g, ' '))) {
        addWeight(weights, token, 1);
      }
    }

    return {
      intent,
      phrases,
      triggers,
      weights,
      exampleTokens: intent.examples.map((example) => new Set(tokenize(example))),
    };
  });
}

function jaccard(a: Set<string>, b: Set<string>): number {
  if (a.size === 0 || b.size === 0) return 0;
  let intersection = 0;
  for (const token of a) {
    if (b.has(token)) intersection++;
  }
  return intersection / (a.size + b.size - intersection);
}

function profileScore(profile: IntentProfile, prompt: string, promptNorm: string, promptTokens: Set<string>): number {
  if (promptNorm.length > 0) {
    for (const phrase of profile.phrases) {
      if (promptNorm === phrase) return 0.95;
      if (promptNorm.includes(phrase)) return 0.94;
      if (phrase.includes(promptNorm) && promptNorm.length >= 8) return 0.9;
    }
  }

  if (profile.triggers.some((trigger) => trigger.test(prompt))) {
    return 0.92;
  }

  let bestExample = 0;
  for (const exampleTokens of profile.exampleTokens) {
    bestExample = Math.max(bestExample, jaccard(promptTokens, exampleTokens));
  }

  let matchedWeight = 0;
  let totalWeight = 0;
  for (const [token, weight] of profile.weights) {
    totalWeight += weight;
    if (promptTokens.has(token)) matchedWeight += weight;
  }
  const idCoverage = totalWeight > 0 ? matchedWeight / totalWeight : 0;
  const promptCoverage =
    promptTokens.size > 0
      ? [...promptTokens].filter((token) => profile.weights.has(token)).length / promptTokens.size
      : 0;

  return clamp01(0.65 * bestExample + 0.25 * idCoverage + 0.1 * promptCoverage);
}

export function scoreIntent(
  profile: IntentProfile,
  prompt: string,
  promptNorm: string,
  promptTokens: Set<string>,
): number {
  return profileScore(profile, prompt, promptNorm, promptTokens);
}

export function classifyPrompt(
  profiles: IntentProfile[],
  prompt: string,
  options: { semanticScorer?: (prompt: string, intent: IntentDefinition) => number } = {},
): IntentCandidate[] {
  const promptNorm = normalizeText(prompt);
  const promptTokens = new Set(tokenize(prompt));
  const candidates: IntentCandidate[] = [];

  for (const profile of profiles) {
    let score = profileScore(profile, prompt, promptNorm, promptTokens);
    if (options.semanticScorer) {
      const semantic = clamp01(options.semanticScorer(prompt, profile.intent));
      score = clamp01(0.8 * score + 0.2 * semantic);
    }
    candidates.push({
      intent: profile.intent.id,
      score: Number(score.toFixed(4)),
      band: bandFor(score),
    });
  }

  candidates.sort((a, b) => b.score - a.score || a.intent.localeCompare(b.intent));
  return candidates;
}

export function findSpan(prompt: string, phrase: string): [number, number] | undefined {
  const index = prompt.toLowerCase().indexOf(phrase.toLowerCase());
  if (index < 0) return undefined;
  return [index, index + phrase.length];
}

import type {
  ApprovalRecord,
  IntentDefinition,
  RiskAssessment,
  RiskLevel,
  UserRef,
} from './types';

const INJECTION_PATTERNS: { kind: string; pattern: RegExp }[] = [
  {
    kind: 'instruction-override',
    pattern: /\b(ignore|disregard|forget)\b.{0,50}\b(previous|prior|above|all)\b.{0,40}\b(instructions?|rules?|prompts?)\b/i,
  },
  { kind: 'instruction-override', pattern: /\bdisregard\s+the\s+(rules|instructions|user)\b/i },
  { kind: 'role-confusion', pattern: /\b(you\s+are\s+now|from\s+now\s+on)\b.{0,50}\b(unrestricted|admin|root|system|developer)\b/i },
  { kind: 'role-confusion', pattern: /\b(unrestricted|developer|god)\s+mode\b/i },
  { kind: 'role-confusion', pattern: /<\s*\/?\s*(system|user|assistant)\s*>/i },
  { kind: 'role-confusion', pattern: /\[\s*\/?\s*(INST|SYS)\s*\]/i },
  { kind: 'role-confusion', pattern: /\b(pretend|act)\b.{0,40}\b(system|admin|root)\b/i },
  {
    kind: 'secret-exfiltration',
    pattern: /\b(reveal|show|print|list|leak|expose)\b.{0,50}\b(api[- ]?keys?|credentials?|secrets?|passwords?)\b/i,
  },
  { kind: 'destructive-tool', pattern: /\b(drop|truncate|delete)\b.{0,30}\b(table|database|schema)\b/i },
  { kind: 'out-of-band-tool', pattern: /\b(internal_admin_panel|grant\s+me\s+admin|grant\s+admin|elevate\s+privileges)\b/i },
  { kind: 'control-bytes', pattern: /[\u202A-\u202E\u2066-\u2069\u200B-\u200D\uFEFF]/ },
  { kind: 'soft-injection', pattern: /#\s*(IMPORTANT|SYSTEM|INSTRUCTION)\b/i },
];

const DESTRUCTIVE = /\b(delete|remove|clear|wipe|destroy|send|drop|revoke|transfer)\b/i;

const EMAIL_PATTERN = /\b[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}\b/gi;
const PHONE_PATTERN = /(?:\+?\d[\d\s().-]{7,}\d)/g;

const CAPITALIZED_STOPWORDS = new Set([
  'a', 'an', 'and', 'at', 'by', 'compare', 'complete', 'create', 'delete', 'do', 'draft', 'email',
  'find', 'for', 'forget', 'from', 'give', 'handle', 'hello', 'how', 'ignore', 'in', 'list', 'mark',
  'move', 'my', 'new', 'of', 'on', 'plan', 'please', 'pull', 'put', 'remember', 'remove', 'rename',
  'research', 'schedule', 'send', 'show', 'summarize', 'the', 'this', 'to', 'translate', 'what',
  'when', 'where', 'which', 'who', 'write', 'you', 'your',
]);

const NUMBER_WORDS: Record<string, number> = {
  one: 1,
  two: 2,
  three: 3,
  four: 4,
  five: 5,
  six: 6,
  seven: 7,
  eight: 8,
  nine: 9,
  ten: 10,
  eleven: 11,
  twelve: 12,
  fifteen: 15,
  twenty: 20,
};

function parseAmount(raw: string, suffix?: string): number {
  const value = Number(raw);
  if (!Number.isFinite(value)) return 0;
  const unit = (suffix ?? '').toLowerCase();
  if (unit === 'k') return value * 1_000;
  if (unit === 'm') return value * 1_000_000;
  return value;
}

function extractAccount(prompt: string): string | undefined {
  const matches = [...prompt.matchAll(/\b([A-Z][A-Za-z0-9&.-]{1,})\b/g)];
  for (const match of matches) {
    const value = match[1];
    const normalized = value.toLowerCase();
    if (CAPITALIZED_STOPWORDS.has(normalized)) continue;
    if (normalized === 'q2' || normalized === 'q1' || normalized === 'q3' || normalized === 'q4') continue;
    if (/^\d+$/.test(value)) continue;
    return value;
  }
  return undefined;
}

function extractSubjects(prompt: string): string[] {
  const match = prompt.match(/\b(?:compare|research)\b(.*)$/i);
  if (!match) return [];
  return match[1]
    .split(/,|\band\b/gi)
    .map((item) => item.trim().replace(/^the\s+/i, '').replace(/\.$/, ''))
    .filter((item) => item.length > 1 && !/^(top|vector databases?|and)$/i.test(item));
}

function extractTitle(prompt: string): string | undefined {
  let value = prompt.trim();
  value = value.replace(/^(please\s+)?(add|create|new)\b(\s+(a|an|the))?\s*(task|to-?do)?\s*(to\s+)?/i, '');
  value = value.replace(/^remind\s+me\s+to\s+/i, '');
  value = value.replace(/^new\s+task\s*[:\-]\s*/i, '');
  value = value.trim();
  return value.length > 0 ? value : undefined;
}

export function extractParameters(intent: IntentDefinition, prompt: string): Record<string, unknown> {
  const params: Record<string, unknown> = {};
  const id = intent.id;

  if (id === 'deal.recover') {
    const digit = prompt.match(/\b(?:top|first|last)?\s*(\d{1,2})\b/i);
    const word = prompt.match(/\b(one|two|three|four|five|six|seven|eight|nine|ten|eleven|twelve|fifteen|twenty)\b/i);
    params['count'] = digit ? Number(digit[1]) : word ? NUMBER_WORDS[word[1].toLowerCase()] : 1;
    if (/\bemail/i.test(prompt)) params['channel'] = 'email';
    else if (/\bcall\b/i.test(prompt)) params['channel'] = 'call';
    else if (/\bslack\b/i.test(prompt)) params['channel'] = 'slack';
    const stage = prompt.match(/\b(negotiation|proposal|discovery|closed[- ]won|closed[- ]lost)\b/i);
    if (stage) params['stage'] = stage[1].toLowerCase().replace(/\s+/g, '-');
  }

  if (id === 'deal.query') {
    const account = extractAccount(prompt);
    if (account) params['account'] = account;
    const stage = prompt.match(/\b(negotiation|proposal|discovery|closed[- ]won|closed[- ]lost)\b/i);
    if (stage) params['stage'] = stage[1].toLowerCase().replace(/\s+/g, '-');
    const min = prompt.match(/\bover\s+\$?(\d+(?:\.\d+)?)\s*([km])?\b/i);
    if (min) params['valueMin'] = parseAmount(min[1], min[2]);
  }

  if (id === 'deal.update') {
    const account = extractAccount(prompt);
    if (account) params['account'] = account;
    const stage = prompt.match(/\b(negotiation|proposal|discovery|closed[- ]won|closed[- ]lost)\b/i);
    if (stage) params['stage'] = stage[1].toLowerCase().replace(/\s+/g, '-');
    const value = prompt.match(/\$(\d+(?:\.\d+)?)\s*([km])?\b/i);
    if (value) params['value'] = parseAmount(value[1], value[2]);
  }

  if (id === 'email.draft') {
    const recipient = prompt.match(/\b(?:to|email)\s+([A-Z][a-z]+)\b/);
    if (recipient) params['recipient'] = recipient[1];
    const topic = prompt.match(/\babout\s+(.+)$/i);
    if (topic) params['topic'] = topic[1].trim().replace(/\.$/, '');
  }

  if (id === 'email.summarize') {
    const account = extractAccount(prompt);
    if (account) params['account'] = account;
    const window = prompt.match(/\b(this week|last week|today|yesterday|this month|last month)\b/i);
    if (window) params['window'] = window[1].toLowerCase();
  }

  if (id === 'email.send') {
    if (/\ball customers\b/i.test(prompt)) params['audience'] = 'all customers';
    const template = prompt.match(/\b(launch announcement|announcement|newsletter)\b/i);
    if (template) params['template'] = template[1].toLowerCase();
  }

  if (id === 'research.comparison') {
    const subjects = extractSubjects(prompt);
    if (subjects.length > 0) params['subjects'] = subjects;
  }

  if (id === 'research.market') {
    const topic = prompt.match(/\b(?:in|about)\s+the\s+(.+?)\s+space\b/i) ?? prompt.match(/\b(?:research|about)\s+(.+)$/i);
    if (topic) params['topic'] = topic[1].trim();
  }

  if (id === 'plan.long-horizon') {
    const horizon = prompt.match(/\b(\d+[- ](?:month|week|year)s?)\b/i);
    if (horizon) params['horizon'] = horizon[1].toLowerCase().replace(/\s+/g, '-');
    params['topic'] = prompt.trim();
  }

  if (id === 'report.summarize') {
    const period = prompt.match(/\b(Q[1-4]|20\d{2})\b/i);
    if (period) params['period'] = period[1].toUpperCase();
    const subject = prompt.match(/\b(?:summarize|pull)\s+(?:the\s+)?(.+)$/i);
    if (subject) params['subject'] = subject[1].trim();
  }

  if (id === 'calendar.create') {
    const when = prompt.match(/\b(?:for|on)\s+(.+)$/i);
    if (when) params['when'] = when[1].trim();
    const title = prompt.match(/\b(?:schedule|put)\s+(?:me\s+)?(?:a\s+)?(.+?)(?:\s+(?:for|on)\b|$)/i);
    if (title) params['title'] = title[1].trim();
  }

  if (id === 'world.query') {
    const account = extractAccount(prompt);
    if (account) params['subject'] = account;
  }

  if (id === 'task.add') {
    const title = extractTitle(prompt);
    if (title) params['title'] = title;
  }

  if (id === 'task.complete' || id === 'task.uncomplete' || id === 'task.delete') {
    let task = prompt
      .replace(/^(please\s+)?(complete|finish|reopen|uncomplete|delete|remove|clear)\b\s*/i, '')
      .replace(/\b(task|to-?do)\b/gi, ' ')
      .replace(/\b(as\s+)?done\b/gi, ' ')
      .trim();
    if (/\bcompleted\b/i.test(prompt)) params['scope'] = 'completed';
    else if (/\ball\b/i.test(prompt)) params['scope'] = 'all';
    task = task.replace(/\s+/g, ' ').trim();
    if (task) params['task'] = task;
  }

  if (id === 'task.rename') {
    const match = prompt.match(/\brename\s+(.+?)\s+to\s+(.+)$/i);
    if (match) {
      params['task'] = match[1].trim();
      params['title'] = match[2].trim().replace(/\.$/, '');
    }
  }

  if (id === 'task.filter') {
    if (/\bactive\b/i.test(prompt)) params['filter'] = 'active';
    else if (/\bcompleted\b/i.test(prompt)) params['filter'] = 'completed';
    else if (/\ball\b/i.test(prompt)) params['filter'] = 'all';
  }

  if (id === 'task.plan') {
    params['goal'] = prompt.trim();
  }

  if (id === 'memory.remember') {
    const content = prompt.replace(/^.*?\bremember\b(\s+that)?\s*/i, '').trim();
    if (content) params['content'] = content;
  }

  if (id === 'memory.recall') {
    params['query'] = prompt.trim();
  }

  if (id === 'memory.forget') {
    const query = prompt.replace(/^.*?\bforget\b\s*/i, '').trim();
    if (query) params['query'] = query;
  }

  return params;
}

export function detectInjection(prompt: string, strict: boolean): { flags: string[]; reason?: string } {
  const flags: string[] = [];
  let reason: string | undefined;
  for (const { kind, pattern } of INJECTION_PATTERNS) {
    if (pattern.test(prompt)) {
      flags.push(kind);
      reason ??= `blocked ${kind} pattern`;
    }
  }
  if (strict && /[\u0000-\u0008\u000B\u000C\u000E-\u001F]/.test(prompt)) {
    flags.push('control-bytes');
    reason ??= 'blocked control characters';
  }
  return { flags, reason };
}

export function redactSensitive(prompt: string): string[] {
  const redactions: string[] = [];
  if (EMAIL_PATTERN.test(prompt)) {
    redactions.push('email');
    EMAIL_PATTERN.lastIndex = 0;
  }
  if (PHONE_PATTERN.test(prompt)) {
    redactions.push('phone');
    PHONE_PATTERN.lastIndex = 0;
  }
  return redactions;
}

export function assessRisk(args: {
  prompt: string;
  intent: IntentDefinition;
  user?: UserRef;
  surface: string;
  strict: boolean;
}): RiskAssessment {
  const injection = detectInjection(args.prompt, args.strict);
  const flags = [...injection.flags];
  const redactions = redactSensitive(args.prompt);
  const approvals: ApprovalRecord[] = [];

  if (injection.flags.length > 0) {
    return {
      level: 'block',
      flags,
      redactions,
      reason: injection.reason,
      approvals: [],
    };
  }

  const role = args.user?.role;
  const roleAllowed = args.intent.roles.includes('*') || (role ? args.intent.roles.includes(role) : false);
  if (!roleAllowed) {
    flags.push('role-not-allowed');
    return {
      level: 'block',
      flags,
      redactions,
      reason: `role "${role ?? 'anonymous'}" cannot invoke ${args.intent.id}`,
      approvals: [],
    };
  }

  if (!args.intent.surfaces.includes(args.surface)) {
    flags.push('surface-not-allowed');
    return {
      level: 'block',
      flags,
      redactions,
      reason: `surface "${args.surface}" cannot invoke ${args.intent.id}`,
      approvals: [],
    };
  }

  let level: RiskLevel = args.intent.riskClass;
  const approvalCapability = args.intent.capabilities.some((capability) =>
    ['approval.require', 'email.send', 'world.assert'].includes(capability),
  );
  if (approvalCapability || args.intent.riskClass === 'high') {
    level = 'high';
  }
  if (DESTRUCTIVE.test(args.prompt) && !/^task\.(list|filter|summary|plan)$/.test(args.intent.id)) {
    if (level === 'low') level = 'medium';
    if (/\b(all|every|everything)\b/i.test(args.prompt)) level = 'high';
  }

  if (level === 'high') {
    approvals.push({
      kind: 'user-confirm',
      status: 'required',
      reason: `${args.intent.id} is a high-risk action`,
    });
    flags.push('approval-required');
  }

  return { level, flags, redactions, approvals };
}

