    const subject = prompt.match(/\b(?:summarize|pull)\s+(?:the\s+)?(.+)$/i);
    if (subject) params['subject'] = subject[1].trim();
  }

  if (id === 'calendar.create') {
    const when = prompt.match(/\b(?:for|on)\s+(.+)$/i);
