import { computed, Injectable, signal } from '@angular/core';
import { HMEM } from '../engines/hmem';
import type { HMEMSnapshot, MemoryRecord, QueryResult } from '../engines/hmem';
import { readJson, writeJson } from './persistence';

const MEMORY_KEY = 'angular-todo-app.hmem.v1';

@Injectable({ providedIn: 'root' })
export class MemoryService {
  private readonly revision = signal(0);
  private readonly hmem = new HMEM({
    actor: 'local-user',
    persistence: {
      load: () => readJson<HMEMSnapshot>(MEMORY_KEY),
      save: (snapshot) => writeJson(MEMORY_KEY, snapshot),
    },
  });

  readonly memories = computed<readonly MemoryRecord[]>(() => {
    this.revision();
    return this.hmem.store
      .all()
      .filter((memory) => !memory.supersededBy)
      .sort((left, right) => right.timestamp - left.timestamp);
  });

  readonly count = computed(() => this.memories().length);

  remember(content: string): MemoryRecord | undefined {
    const trimmed = content.trim();

    if (!trimmed) {
      return undefined;
    }

    const record = this.hmem.add({
      content: trimmed,
      type: /\b(prefer|like|love|hate|dislike)\b/i.test(trimmed) ? 'preference' : 'general',
      layer: 'long_term',
      tags: ['user', 'explicit'],
      confidence: 0.8,
      source: 'user',
    });
    this.revision.update((value) => value + 1);
    return record;
  }

  recall(query: string): QueryResult {
    const result = this.hmem.query(query, { threshold: 0.2, topN: 5 });
    this.hmem.store.persist();
    this.revision.update((value) => value + 1);
    return result;
  }

  forget(query: string): MemoryRecord | undefined {
    const result = this.recall(query);
    const target = result.memories[0]?.memory;

    if (!target) {
      return undefined;
    }

    this.hmem.store.delete(target.id, `user requested: ${query}`);
    this.revision.update((value) => value + 1);
    return target;
  }

  delete(id: string): void {
    this.hmem.store.delete(id, 'removed from memory panel');
    this.revision.update((value) => value + 1);
  }
}

import { computed, Injectable, signal } from '@angular/core';
import { externalId, WorldModel } from '../engines/world-model';
import type { AuditEntry, Entity, WorldEvent } from '../engines/world-model';
import type { Task } from '../models/task.model';
import { readJson, writeJson } from './persistence';

const WORLD_KEY = 'angular-todo-app.world.v1';

@Injectable({ providedIn: 'root' })
export class WorldModelService {
  private readonly revision = signal(0);
  private readonly world = new WorldModel({
    namespace: 'todo',
    storage: 'memory',
    persistence: {
      load: () => readJson(WORLD_KEY),
      save: (snapshot) => writeJson(WORLD_KEY, snapshot),
    },
  });

  readonly taskEntities = computed(() => {
    this.revision();
    return this.world
      .view('graph')
      .query({ type: 'task' })
      .filter((entity) => entity.state === 'active');
  });

  readonly recentEvents = computed<readonly WorldEvent[]>(() => {
    this.revision();
    return [...this.world.events()].slice(-6).reverse();
  });

  readonly recentAudit = computed<readonly AuditEntry[]>(() => {
    this.revision();
    return [...this.world.audit()].slice(-6).reverse();
  });

  readonly eventCount = computed(() => {
    this.revision();
    return this.world.events().length;
  });

  upsertTask(task: Task): void {
    const id = this.entityId(task.id);
    const existing = this.world.view('graph').entity(id);

    if (
      existing &&
      existing.state === 'active' &&
      existing.name === task.title &&
      existing.attrs['completed'] === task.completed
    ) {
      return;
    }

    this.world.upsertEntitySync({
      type: 'task',
      externalKey: { system: 'todo', id: task.id },
      name: task.title,
      attrs: {
        title: task.title,
        completed: task.completed,
        createdAt: task.createdAt,
      },
      source: { kind: 'user', by: 'local-user', at: new Date().toISOString() },
    });
    this.revision.update((value) => value + 1);
  }

  archiveTask(task: Task): void {
    try {
      this.world.tombstoneSync(this.entityId(task.id), 'task deleted', {
        kind: 'user',
        by: 'local-user',
        at: new Date().toISOString(),
      });
      this.revision.update((value) => value + 1);
    } catch {
      // The task may predate World Model persistence; nothing to archive.
    }
  }

  entityFor(task: Task): Entity | undefined {
    return this.world.view('graph').entity(this.entityId(task.id));
  }

  private entityId(taskId: string): string {
    return externalId('task', 'todo', taskId);
  }
}

