}

export class MemoryStoreService {
  private records = new Map<string, MemoryRecord>();
  private seq = 0;

  constructor(
    private clock: () => number,
    private ledger: TrustLedgerService,
    private actor: string,
    private onChange?: () => void,
  ) {}

  persist(): void {
    this.onChange?.();
  }

  add(input: AddInput): MemoryRecord {
    if (!input.source || input.source.trim() === '') {
      throw new Error(
        'H-MEM: a memory record with no source must be rejected by construction (AGENTS.md section 2)',
      );
    }
    const now = this.clock();
    const id = `mem-${++this.seq}`;
    const tags = [...(input.tags ?? [])];
    const domain = this.classifyDomain(input.content, tags, input.type ?? 'general');
    const record: MemoryRecord = {
      id,
      content: input.content,
      type: input.type ?? 'general',
      layer: input.layer ?? 'working',
      timestamp: now,
      lastAccessed: now,
      accessCount: 0,
      tags,
      embedding: embed(input.content),
      confidence: clamp01(input.confidence ?? 0.7),
      source: input.source,
      provenance: input.provenance ?? { origin: 'manual', learnedAt: now, label: input.source },
      chatId: input.chatId,
      missionId: input.missionId,
      goalRunId: input.goalRunId,
      domain,
      namespace: this.namespace(domain, input.type ?? 'general'),
      entities: this.extractEntities(input.content),
      relatedTo: [],
      supersedes: input.supersedes,
      derivedFrom: input.derivedFrom,
    };
    this.discoverRelationships(record);
    this.records.set(id, record);
    this.ledger.log(id, 'create', this.actor, { newState: snapshot(record) });
    this.persist();
    return record;
  }

  get(id: string): MemoryRecord | undefined {
    return this.records.get(id);
  }

  all(): MemoryRecord[] {
    return [...this.records.values()];
  }

  update(id: string, patch: Partial<MemoryRecord>): MemoryRecord {
    const rec = this.mustGet(id);
    const prev = snapshot(rec);
    Object.assign(rec, patch);
    this.ledger.log(id, 'update', this.actor, { previousState: prev, newState: snapshot(rec) });
    this.persist();
    return rec;
  }

  delete(id: string, reason: string): void {
    const rec = this.mustGet(id);
    this.records.delete(id);
    this.ledger.log(id, 'delete', this.actor, {
      previousState: snapshot(rec),
      details: { reason },
    });
    this.persist();
  }

  touch(id: string): void {
    const rec = this.mustGet(id);
    rec.lastAccessed = this.clock();
    rec.accessCount += 1;
  }

  promote(id: string, layer: MemoryLayer): void {
    const rec = this.mustGet(id);
    const prev = snapshot(rec);
    rec.layer = layer;
    this.ledger.log(id, 'promote', this.actor, { previousState: prev, newState: snapshot(rec) });
    this.persist();
  }

  restoreAll(records: MemoryRecord[], seq: number): void {
    this.records = new Map(records.map((r) => [r.id, structuredClone(r)]));
    this.seq = seq;
    this.persist();
  }

  snapshotAll(): { records: MemoryRecord[]; seq: number } {
    return { records: structuredClone([...this.records.values()]), seq: this.seq };
  }

  private mustGet(id: string): MemoryRecord {
    const rec = this.records.get(id);
    if (!rec) throw new Error(`H-MEM: unknown memory id ${id}`);
    return rec;
  }

  // Multi-pass domain classification (AGENTS.md section 5).
  classifyDomain(content: string, tags: string[], type: MemoryType): string {
    for (const t of tags) {
      if (t.startsWith('project:')) return t.slice('project:'.length);
      if (t.startsWith('tech:')) return 'tech';
    }
    const tokens = new Set(tokenize(content));
    let best = 'general';
    let bestScore = 0;
    for (const [domain, kws] of Object.entries(DOMAIN_KEYWORDS)) {
      let score = kws.reduce((s, kw) => s + (tokens.has(kw) ? 1 : 0), 0);
      if (domain === 'personal' && (type === 'personal' || type === 'preference')) score += 1;
      if (score > bestScore) {
        best = domain;
        bestScore = score;
      }
    }
    return bestScore > 0 ? best : 'general';
  }

  private namespace(domain: string, type: MemoryType): string {
    const bucket =
      type === 'preference' || type === 'personal'
        ? 'profile'
        : type === 'factual'
          ? 'facts'
          : 'notes';
    return `${domain}/${bucket}`;
  }

  extractEntities(content: string): string[] {
    const entities = new Set<string>();
    for (const t of tokenize(content)) if (TECH_TERMS.includes(t)) entities.add(t);
    for (const m of content.matchAll(/\b([A-Z][a-zA-Z]{2,})\b/g)) {
      const norm = m[1].toLowerCase();
      if (!['the', 'this', 'that', 'with'].includes(norm)) entities.add(norm);
    }
    return [...entities].slice(0, DEFAULTS.entityCap);
  }

  private discoverRelationships(record: MemoryRecord): void {
    const CORRECTION = /\b(actually|instead|no longer|not anymore|changed to|correction)\b/i;
    for (const other of this.records.values()) {
      if (record.relatedTo.length >= DEFAULTS.relatedCap) break;
      const sharedEntities = other.entities.filter((e) => record.entities.includes(e));
      const sim = cosine(record.embedding, other.embedding);
      if (!record.supersedes && sim > 0.85 && CORRECTION.test(record.content)) {
        record.supersedes = other.id;
        continue;
      }
      if (sharedEntities.length >= 1 && other.domain === record.domain) {
        record.relatedTo.push(other.id);
        if (other.relatedTo.length < DEFAULTS.relatedCap && !other.relatedTo.includes(record.id)) {
          other.relatedTo.push(record.id); // bidirectional link
        }
      }
    }
  }
}

export function snapshot(r: MemoryRecord): Partial<MemoryRecord> {
  const { embedding, ...rest } = structuredClone(r);
  return rest;
}

/**
 * Record shapes for the World Model reference implementation.
 *
 * Source of truth: AGENTS.md section 2 and docs/aggregate-shapes.md.
 * The five write primitives are upsertEntity, upsertContext, relate,
 * assertFact, and snapshot. Everything else is derived.
 */

export type ISODate = string;

export type EntityId = string;
export type ContextId = string;
export type RelationshipId = string;
export type FactId = string;
export type EventId = string;

/** Every write carries provenance. No provenance, no write (rejected at the boundary). */
export type Provenance = {
  kind: 'manual' | 'rss' | 'api' | 'file' | 'agent' | 'pipeline' | 'wire' | (string & {});
  /** user id, pipeline id, agent id */
  by?: string;
  /** observation timestamp. Record timestamps derive from this, never from wall clock. */
  at: ISODate | Date;
  url?: string;
  checksum?: string;
  /** ingest/replay run identifier, joins events to a run */
  runId?: string;
};

/** Provenance after normalization: `at` is always an ISO string internally. */
export type StoredProvenance = Omit<Provenance, 'at'> & { at: ISODate };

/**
 * Entity record layers per AGENTS.md section 2.2:
 * identity / semantics (attrs) / continuity anchors (aliases, embedding) /
 * aggregates (rollups) / provenance / lifecycle.
 */
export type Entity = {
  type: string;
  id: EntityId;
  attrs: Record<string, unknown>;
  schemaVersion: number;
  source: StoredProvenance;
  createdAt: ISODate;
  updatedAt: ISODate;
  /** canonical display name, when known */
  name?: string;
  /** every name the sources used; continuity anchor + merge survivor set */
  aliases: string[];
  /** lifecycle */
  state: 'emerging' | 'active' | 'archived';
  /** cheap-to-read rollups, recomputed by pipeline step 9 (rebuild aggregates) */
  aggregates?: {
    mentionCount: number;
    firstSeenAt?: ISODate;
    lastSeenAt?: ISODate;
    linkedStoryIds: string[];
  };
};

export type Context = {
  type: string;
  id: ContextId;
  attrs: Record<string, unknown>;
  parent?: ContextId;
  startedAt?: ISODate;
  endedAt?: ISODate;
  schemaVersion: number;
  source: StoredProvenance;
  createdAt: ISODate;
  updatedAt: ISODate;
};

/**
 * Bitemporal edge. `validTo` unset means open-ended. A superseding observation
 * CLOSES the old edge (sets validTo) and opens a new one; it never deletes.
 */
export type Relationship = {
  id: RelationshipId;
  from: EntityId;
  type: string;
  to: EntityId;
  context?: ContextId;
  attrs?: Record<string, unknown>;
  validFrom?: ISODate;
  validTo?: ISODate;
  schemaVersion: number;
  source: StoredProvenance;
  createdAt: ISODate;
  /** set when a superseding relate closed this edge */
  supersededBy?: RelationshipId;
};

export type Fact = {
  id: FactId;
  about: EntityId;
  predicate: string;
  value: unknown;
  confidence: number;
  context?: ContextId;
  source: StoredProvenance;
  assertedAt: ISODate;
  supersededBy?: FactId;
};

export type Snapshot = {
  id: string;
  at: ISODate;
  context?: ContextId;
  entities: EntityId[];
  attrs?: Record<string, unknown>;
  schemaVersion: number;
  source: StoredProvenance;
};

export type Tombstone = {
  targetId: string;
  reason?: string;
  at: ISODate;
  by?: string;
};

export type Alias = {
  aliasId: EntityId;
  primaryId: EntityId;
  mergedAt: ISODate;
  mergedBy: string;
  reason: string;
};

export type ViewRebuild = {
  view: string;
  at: ISODate;
  durationMs: number;
  eventsReplayed: number;
};

export type EventKind =
  | 'upsertEntity'
  | 'upsertContext'
  | 'relate'
  | 'assertFact'
  | 'snapshot'
  | 'tombstone'
  | 'alias'
  | 'view-rebuild';

/** Append-only log entry. State is a fold over events; views are projections of the fold. */
export type WorldEvent = {
  id: EventId;
  /** monotonic within the namespace; determined by append order, not writer clocks */
  seq: number;
  kind: EventKind;
  payload: Entity | Context | Relationship | Fact | Snapshot | Tombstone | Alias | ViewRebuild;
  schemaVersion: number;
  at: ISODate;
};

/* ------------------------------------------------------------------ */
/* Aggregate shapes (AGENTS.md section 2.1)                            */
/* ------------------------------------------------------------------ */

/** Timeline aggregate (Example A): a history of snapshots. */
export type TimelineAggregate = {
  id: string;
  name: string;
  snapshots: Snapshot[];
  activeSnapshotIndex: number;
  registries: Record<string, EntityId[]>;
};

/** Stream-cluster aggregate (Example B): raw items clustered into stories. */
export type StoryAggregate = {
  id: string;
  title: string;
  /** observation ids, sorted */
  memberIds: string[];
  /** normalized entity names mentioned across members, sorted */
  entityNames: string[];
  /** resolved entity ids, sorted */
  entityIds: EntityId[];
  /** distinct provenance kinds/urls across members, sorted */
  sources: string[];
  firstAt: ISODate;
  lastAt: ISODate;
  /** derived records inferred in pipeline step 5 */
  milestones: { kind: string; at: ISODate }[];
};

/** Pure graph aggregate: nodes + bitemporal edges. */
export type GraphAggregate = {
  nodes: { id: string; type: string; properties: Record<string, unknown> }[];
  edges: Relationship[];
};

/** Per-story score snapshot, persisted by pipeline step 4 (score / measure). */
export type ScoreSnapshot = {
  storyId: string;
  at: ISODate;
  /** velocity(w) = mentions in window w / hours(w), over bucketed windows */
  velocity1h: number;
  velocity24h: number;
  velocity7d: number;
  /** sign(velocity(current hour bucket) - velocity(previous hour bucket)) */
  trendDirection: -1 | 0 | 1;
};

/* ------------------------------------------------------------------ */
/* Ingest and operator surfaces                                        */
/* ------------------------------------------------------------------ */

/** A raw observation entering the batch/stream ingest cycle. */
export type IngestObservation = {
  /** stable external identifier; the dedupe key derives from it */
  externalId: string;
  /** entity type the observation materializes as (default "item") */
  type?: string;
  title: string;
  text?: string;
  /** the observation timestamp; every derived record timestamp comes from here */
  at: ISODate;
  source: Provenance;
  /** entities mentioned by this observation */
  entities?: { type: string; name: string }[];
};

/** Stored, patched form of an observation (pipeline step 8 writes computed fields back). */
export type ObservationRecord = {
  id: string;
  externalId: string;
  entityId: EntityId;
  checksum: string;
  at: ISODate;
  storyId?: string;
  entityIds?: EntityId[];
  syncedAt?: ISODate;
  stale: boolean;
};

/** An entry in the operator merge-review queue. */
export type MergeProposal = {
  id: string;
  leftId: EntityId;
  rightId: EntityId;
  leftName: string;
  rightName: string;
  similarity: number;
  reason: string;
  status: 'pending' | 'approved' | 'rejected';
  proposedAt: ISODate;
  resolvedAt?: ISODate;
  resolvedBy?: string;
};

/** Audit log entry. Every mutation writes one; the control plane reads this. */
export type AuditEntry = {
  seq: number;
  at: ISODate;
  kind: string;
  actor: string;
  summary: string;
  eventId?: EventId;
  runId?: string;
};

export type ConflictPolicy =
  'most-recent-wins' | 'highest-confidence-wins' | 'source-priority' | 'manual';

export type ResolverOptions = {
  strategy?: string | string[];
  /**
   * Similarity at or above this auto-merges.
   * Default 0.85 (see resolve.ts for the banding ruling).
   */
  autoMergeAt?: number;
  /** [lower, upper): queue for operator review. Default [0.82, autoMergeAt). */
  reviewBand?: [number, number];
};

/** Serializable form of the event store, used by injected persistence adapters. */
export type WorldSnapshot = {
  events: WorldEvent[];
  audit: AuditEntry[];
  observations: [string, ObservationRecord][];
  stories: [string, StoryAggregate][];
  scores: ScoreSnapshot[];
  mergeQueue: MergeProposal[];
};

export interface WorldPersistence {
  load(): WorldSnapshot | undefined;
  save(snapshot: WorldSnapshot): void;
}

export type WorldModelOptions = {
  /** "memory" keeps state in-process; "local" persists to .world/<namespace>.json */
  storage?: 'memory' | 'local';
  namespace: string;
  /** base directory for legacy "local" storage (unused by the browser port) */
  directory?: string;
  /** Injected persistence adapter; the core has no filesystem dependency. */
  persistence?: WorldPersistence;
  /**
   * Injectable clock, used ONLY for genuinely-now operator actions
   * (merge approvals, view rebuilds, repair). Record timestamps always
   * derive from observation timestamps so ingest stays idempotent.
   */
  clock?: () => Date;
  resolver?: ResolverOptions;
  conflictPolicy?: ConflictPolicy;
  /** source-priority ranking, highest priority first (used by that policy) */
  sourcePriority?: string[];
};

export type IngestReport = {
  runId: string;
  processed: number;
  skippedUnchanged: number;
  clusters: number;
  eventsAppended: number;
  changed: boolean;
  /** wall-clock step timings; reported only, never persisted into state */
  stepTimingsMs: { step: number; name: string; ms: number }[];
};

