  'your',
]);

export function normalizeText(text: string): string {
  return text
    .normalize('NFKD')
    .replace(/[\u0300-\u036f]/g, '')
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();
}

export function tokenize(text: string): string[] {
  return normalizeText(text)
    .split(' ')
    .filter((token) => token.length > 1 && !STOPWORDS.has(token));
}

export function bandFor(score: number): ConfidenceBand {
  if (score >= 0.8) return 'high';
  if (score >= 0.55) return 'medium';
  if (score >= 0.4) return 'low';
  return 'reject';
}

export function clamp01(value: number): number {
  return Math.min(1, Math.max(0, value));
}

interface IntentProfile {
  intent: IntentDefinition;
  phrases: string[];
  triggers: RegExp[];
  weights: Map<string, number>;
  exampleTokens: Set<string>[];
}

function addWeight(weights: Map<string, number>, token: string, weight: number): void {
  weights.set(token, Math.max(weights.get(token) ?? 0, weight));
}

export function buildProfiles(registry: IntentRegistry): IntentProfile[] {
  return registry.intents.map((intent) => {
    const weights = new Map<string, number>();
    const phrases = intent.examples.map(normalizeText).filter(Boolean);
    const triggers: RegExp[] = [];
    for (const trigger of intent.triggers ?? []) {
      try {
        triggers.push(new RegExp(trigger, 'i'));
      } catch {
        // A bad trigger is a registry bug; validation remains deterministic.
      }
    }

    for (const part of intent.id.split(/[.-]/)) {
      if (part.length > 1) addWeight(weights, part, 3);
    }
    addWeight(weights, intent.category, 1);
    for (const token of tokenize(intent.description)) addWeight(weights, token, 0.7);
    for (const example of intent.examples) {
      for (const token of tokenize(example)) addWeight(weights, token, 1.5);
    }
    for (const trigger of intent.triggers ?? []) {
      for (const token of tokenize(trigger.replace(/[\\^$.*+?()[\]{}|]/g, ' '))) {
        addWeight(weights, token, 1);
      }
    }

    return {
      intent,
      phrases,
      triggers,
      weights,
      exampleTokens: intent.examples.map((example) => new Set(tokenize(example))),
    };
  });
}

function jaccard(a: Set<string>, b: Set<string>): number {
  if (a.size === 0 || b.size === 0) return 0;
  let intersection = 0;
  for (const token of a) {
    if (b.has(token)) intersection++;
  }
  return intersection / (a.size + b.size - intersection);
}

function profileScore(
  profile: IntentProfile,
  prompt: string,
  promptNorm: string,
  promptTokens: Set<string>,
): number {
  if (promptNorm.length > 0) {
    for (const phrase of profile.phrases) {
      if (promptNorm === phrase) return 0.95;
      if (promptNorm.includes(phrase)) return 0.95;
      if (phrase.includes(promptNorm) && promptNorm.length >= 8) return 0.93;
    }
  }

  if (profile.triggers.some((trigger) => trigger.test(prompt))) {
    return 0.95;
  }

  let bestExample = 0;
  for (const exampleTokens of profile.exampleTokens) {
    bestExample = Math.max(bestExample, jaccard(promptTokens, exampleTokens));
  }

  let matchedWeight = 0;
  let totalWeight = 0;
  for (const [token, weight] of profile.weights) {
    totalWeight += weight;
    if (promptTokens.has(token)) matchedWeight += weight;
  }
  const idCoverage = totalWeight > 0 ? matchedWeight / totalWeight : 0;
  const promptCoverage =
    promptTokens.size > 0
      ? [...promptTokens].filter((token) => profile.weights.has(token)).length / promptTokens.size
      : 0;

  return clamp01(0.65 * bestExample + 0.25 * idCoverage + 0.1 * promptCoverage);
}

export function scoreIntent(
  profile: IntentProfile,
  prompt: string,
  promptNorm: string,
  promptTokens: Set<string>,
): number {
  return profileScore(profile, prompt, promptNorm, promptTokens);
}

export function classifyPrompt(
  profiles: IntentProfile[],
  prompt: string,
  options: { semanticScorer?: (prompt: string, intent: IntentDefinition) => number } = {},
): IntentCandidate[] {
  const promptNorm = normalizeText(prompt);
  const promptTokens = new Set(tokenize(prompt));
  const candidates: IntentCandidate[] = [];

  for (const profile of profiles) {
    let score = profileScore(profile, prompt, promptNorm, promptTokens);
    if (options.semanticScorer) {
      const semantic = clamp01(options.semanticScorer(prompt, profile.intent));
      score = clamp01(0.8 * score + 0.2 * semantic);
    }
    candidates.push({
      intent: profile.intent.id,
      score: Number(score.toFixed(4)),
      band: bandFor(score),
    });
  }

  candidates.sort((a, b) => b.score - a.score || a.intent.localeCompare(b.intent));
  return candidates;
}

export function findSpan(prompt: string, phrase: string): [number, number] | undefined {
  const index = prompt.toLowerCase().indexOf(phrase.toLowerCase());
  if (index < 0) return undefined;
  return [index, index + phrase.length];
}

// Hybrid retrieval and reinjection (AGENTS.md section 6). The canonical formula:
//
//   raw = 0.35*semantic + 0.20*keyword + 0.10*tag + 0.10*domain
//       + 0.15*entity   + 0.05*layer   + 0.05*recency - 0.20*superseded
//   score = clamp01(raw) * confidence          <- confidence multiplies AFTER the sum
//
// keyword = Jaccard of the top-8 query tokens vs memory tokens.
// layer weights: long_term 1.0, working 0.8, short_term 0.6.
// recency = exponential decay on lastAccessed, 14-day time constant.
// superseded records are penalized, never deleted or filtered.
// Threshold 0.35 applies to the FINAL score; top N = 5.

import { DAY_MS, DEFAULTS, clamp01 } from './types';
import type { MemoryRecord, QueryResult, RetrievedMemory } from './types';
import { cosine, embed, jaccard, tokenize } from './embeddings';
import type { MemoryStoreService } from './memoryStore';
import type { TrustLedgerService } from './trustLedger';
import { FEEDBACK_DELTAS } from './types';
import type { FeedbackKind } from './types';
import { snapshot } from './memoryStore';

const LAYER_WEIGHT: Record<MemoryRecord['layer'], number> = {
  long_term: 1.0,
  working: 0.8,
  short_term: 0.6,
};

export class MemoryRetrievalService {
  constructor(
    private store: MemoryStoreService,
    private ledger: TrustLedgerService,
    private clock: () => number,
    private actor: string,
  ) {}

  scoreOne(memory: MemoryRecord, query: string): number {
    const queryEmbedding = embed(query);
    const queryTokens = tokenize(query).slice(0, 8);
    const queryEntities = this.store.extractEntities(query);
    const queryDomain = this.store.classifyDomain(query, [], 'general');
    return this.score(memory, queryEmbedding, queryTokens, queryEntities, queryDomain);
  }

  private score(
    m: MemoryRecord,
    queryEmbedding: number[],
    queryTokens: string[],
    queryEntities: string[],
    queryDomain: string,
  ): number {
    const semantic = clamp01(cosine(queryEmbedding, m.embedding));
    const keyword = jaccard(queryTokens, tokenize(m.content));
    const tag = jaccard(
      queryTokens,
      m.tags.map((t) => t.toLowerCase()),
    );
    const domain = m.domain === queryDomain ? 1 : 0;
    const entity = jaccard(queryEntities, m.entities);
    const layer = LAYER_WEIGHT[m.layer];
    const ageDays = (this.clock() - m.lastAccessed) / DAY_MS;
    const recency = Math.exp(-ageDays / DEFAULTS.recencyDays);
    const superseded = m.supersededBy ? 1 : 0;
    const raw =
      0.35 * semantic +
      0.2 * keyword +
      0.1 * tag +
      0.1 * domain +
      0.15 * entity +
      0.05 * layer +
      0.05 * recency -
      0.2 * superseded;
    return clamp01(raw) * m.confidence;
  }

  query(query: string, opts?: { topN?: number; threshold?: number; chatId?: string }): QueryResult {
    const queryEmbedding = embed(query);
    const queryTokens = tokenize(query).slice(0, 8);
    const queryEntities = this.store.extractEntities(query);
    const queryDomain = this.store.classifyDomain(query, [], 'general');
    const threshold = opts?.threshold ?? DEFAULTS.retrievalThreshold;
    const topN = opts?.topN ?? DEFAULTS.retrievalTopN;

    const scored: RetrievedMemory[] = [];
    for (const m of this.store.all()) {
      if (opts?.chatId && m.chatId && m.chatId !== opts.chatId) continue;
      const s = this.score(m, queryEmbedding, queryTokens, queryEntities, queryDomain);
      if (s >= threshold) scored.push({ memory: m, relevance: s });
    }
    scored.sort((a, b) => b.relevance - a.relevance || a.memory.id.localeCompare(b.memory.id));
    const top = scored.slice(0, topN);

    for (const { memory } of top) {
      this.store.touch(memory.id);
      this.ledger.log(memory.id, 'read', this.actor, { details: { query } });
    }

    const strategy =
      top.length <= 1
        ? 'minimal'
        : top.some((t) => t.memory.type === 'personal' || t.memory.type === 'preference')
          ? 'personal'
          : 'comprehensive';
    return {
      memories: top,
      context: this.formatReinjection(top),
      trace: {
        retrievalReason: `hybrid ranking for "${query}" (domain: ${queryDomain})`,
        strategy,
        scores: Object.fromEntries(top.map((t) => [t.memory.id, Number(t.relevance.toFixed(4))])),
      },
    };
  }

  // Domain-grouped reinjection blocks with layer markers and entities (section 6.2).
  formatReinjection(items: RetrievedMemory[]): string {
    if (items.length === 0) return '';
    const byDomain = new Map<string, RetrievedMemory[]>();
    for (const it of items) {
      const list = byDomain.get(it.memory.domain) ?? [];
      list.push(it);
      byDomain.set(it.memory.domain, list);
    }
    const lines: string[] = ['[MEMORY CONTEXT]'];
    for (const [domain, list] of [...byDomain.entries()].sort()) {
      lines.push(`## ${domain}`);
      for (const { memory } of list) {
        const marker =
          memory.layer === 'long_term' ? 'LT' : memory.layer === 'working' ? 'WK' : 'ST';
        const ents = memory.entities.length ? ` (entities: ${memory.entities.join(', ')})` : '';
        lines.push(`- [${marker}] ${memory.content}${ents} <${memory.id}>`);
      }
    }
    lines.push('[/MEMORY CONTEXT]');
    return lines.join('\n');
  }

  // Exact feedback deltas (AGENTS.md section 9.2).
  feedback(memoryId: string, kind: FeedbackKind): void {
    const m = this.store.get(memoryId);
    if (!m) throw new Error(`H-MEM: unknown memory id ${memoryId}`);
    const prev = snapshot(m);
    if (kind === 'helpful') m.accessCount += 1;
    m.confidence = clamp01(m.confidence + FEEDBACK_DELTAS[kind]);
    if (kind === 'wrong' && !m.tags.includes('review')) m.tags.push('review');
    this.ledger.log(memoryId, 'feedback', this.actor, {
      previousState: prev,
      newState: snapshot(m),
      details: { kind, delta: FEEDBACK_DELTAS[kind] },
    });
    this.store.persist();
  }
}

=== conflict ===
// Conflict detection and resolution (AGENTS.md section 10). The losing record
// is marked supersededBy (kept, penalized in ranking), never deleted.
// Auto-resolve only at decision confidence >= 0.70; everything else queues.

import { DEFAULTS, clamp01 } from './types';
import type { ConflictRecord, MemoryRecord } from './types';
import { cosine } from './embeddings';
import type { MemoryStoreService } from './memoryStore';
import { snapshot } from './memoryStore';
import type { TrustLedgerService } from './trustLedger';

const OPPOSING_PAIRS: [RegExp, RegExp][] = [
  [/\balways\b/i, /\bnever\b/i],
  [/\benable[ds]?\b/i, /\bdisable[ds]?\b/i],
  [/\bprefer[s]?\b/i, /\bavoid[s]?|dislike[s]?\b/i],
  [/\bon\b/i, /\boff\b/i],
  [/\byes\b/i, /\bno\b/i],
];

export class ConflictDetectionService {
  private conflicts: ConflictRecord[] = [];
  private seq = 0;

  constructor(
    private store: MemoryStoreService,
    private ledger: TrustLedgerService,
    private clock: () => number,
    private actor: string,
  ) {}

  scan(): ConflictRecord[] {
    const found: ConflictRecord[] = [];
    const all = this.store.all();
    for (let i = 0; i < all.length; i++) {
      for (let j = i + 1; j < all.length; j++) {
        const conflict = this.check(all[i], all[j]);
        if (conflict) {
          found.push(conflict);
          this.conflicts.push(conflict);
          this.ledger.log(conflict.memoryA, 'conflict_detected', this.actor, {
            details: {
              with: conflict.memoryB,
              reason: conflict.reason,
              confidence: conflict.confidence,
            },
          });
        }
      }
    }
    return found;
  }

  private check(a: MemoryRecord, b: MemoryRecord): ConflictRecord | undefined {
    // supersedes relation suppresses conflict: it is an intended replacement.
    if (
      a.supersedes === b.id ||
      b.supersedes === a.id ||
      a.supersededBy === b.id ||
      b.supersededBy === a.id
    )
      return undefined;

    const sim = cosine(a.embedding, b.embedding);
    let reason = '';
    let confidence = 0;

    for (const [p, q] of OPPOSING_PAIRS) {
      if ((p.test(a.content) && q.test(b.content)) || (q.test(a.content) && p.test(b.content))) {
        if (sim > 0.5) {
          reason = 'opposing phrase pair on similar content';
          confidence = 0.5 + 0.3 * sim;
        }
      }
    }
    if (!reason && sim > 0.8) {
      const numsA = a.content.match(/\d+(\.\d+)?/g) ?? [];
      const numsB = b.content.match(/\d+(\.\d+)?/g) ?? [];
      if (numsA.length && numsB.length && numsA.join() !== numsB.join()) {
        reason = 'high-similarity conflicting numeric values';
        confidence = 0.55 + 0.25 * sim;
      }
    }
    if (!reason) return undefined;

    // Confidence modifiers (section 10.1).
    const sharedEntities = a.entities.filter((e) => b.entities.includes(e));
    if (sharedEntities.length > 0) confidence += 0.1;
    if (a.domain === b.domain) confidence += 0.05;
    if (a.relatedTo.includes(b.id)) confidence -= 0.1; // explicit relation lowers false positives

    return {
      id: `conflict-${++this.seq}`,
      memoryA: a.id,
      memoryB: b.id,
      reason,
      confidence: clamp01(confidence),
      resolved: false,
    };
  }

  // Weighted auto-decision heuristics (section 10.2).
  autoResolve(conflict: ConflictRecord): 'resolved' | 'queued' {
    const a = this.store.get(conflict.memoryA)!;
    const b = this.store.get(conflict.memoryB)!;
    const scoreOf = (m: MemoryRecord) =>
      0.3 * (m.lastAccessed / Math.max(1, this.clock())) +
      0.2 * Math.min(1, m.accessCount / 10) +
      0.25 * m.confidence +
      0.1 * Math.min(1, m.content.length / 200) +
      0.15 * (m.provenance.origin === 'user_correction' ? 1 : 0.5);
    const sa = scoreOf(a);
    const sb = scoreOf(b);
    const margin = Math.abs(sa - sb) / Math.max(sa, sb);
    const decisionConfidence = clamp01(conflict.confidence * 0.6 + margin * 0.8);

    if (decisionConfidence < DEFAULTS.conflictAutoResolveGate) return 'queued';

    const winner = sa >= sb ? a : b;
    const loser = sa >= sb ? b : a;
    const prev = snapshot(loser);
    loser.supersededBy = winner.id; // kept and penalized, never deleted
    conflict.resolved = true;
    conflict.resolution = winner.id === conflict.memoryA ? 'keep_a' : 'keep_b';
    this.ledger.log(loser.id, 'conflict_resolved', this.actor, {
      previousState: prev,
      newState: snapshot(loser),
      details: {
        conflictId: conflict.id,
        winner: winner.id,
        decisionConfidence: Number(decisionConfidence.toFixed(3)),
      },
    });
    this.store.persist();
    return 'resolved';
  }

  queue(): ConflictRecord[] {
    return this.conflicts.filter((c) => !c.resolved);
  }
}

=== trust ===
// Append-only trust ledger (AGENTS.md section 9.1). Entries are never
// mutated or deleted. history() reconstructs a memory's full change record
// from the previousState/newState snapshots carried on each entry.

import type { LedgerAction, LedgerEntry, MemoryRecord } from './types';

export class TrustLedgerService {
  private entries: LedgerEntry[] = [];

  constructor(
    private clock: () => number,
    private onChange?: () => void,
  ) {}

  log(
    memoryId: string,
    action: LedgerAction,
    actor: string,
    extra?: {
      previousState?: Partial<MemoryRecord>;
      newState?: Partial<MemoryRecord>;
      details?: Record<string, unknown>;
    },
  ): LedgerEntry {
    const entry: LedgerEntry = { memoryId, action, actor, timestamp: this.clock(), ...extra };
    this.entries.push(entry);
    this.onChange?.();
    return entry;
  }

  history(memoryId: string): LedgerEntry[] {
    return this.entries.filter((e) => e.memoryId === memoryId);
  }

  all(): readonly LedgerEntry[] {
    return this.entries;
  }

  stats(): Record<string, number> {
    const out: Record<string, number> = {};
    for (const e of this.entries) out[e.action] = (out[e.action] ?? 0) + 1;
    return out;
  }

  snapshot(): LedgerEntry[] {
    return structuredClone(this.entries);
  }

  restoreAll(entries: LedgerEntry[]): void {
    this.entries = structuredClone(entries);
  }
}

// Persistent history service (AGENTS.md section 4.7). The reference persists
// to a JSON file instead of IndexedDB; the contract is identical. The per-run
// chunkConfig snapshot is mandatory and historical efficiency is always
// recomputed against it (section 14).

import { runEfficiency } from './configManager';
import type { CumulativeStats, HistoryPersistence, MarkovianRun } from './types';

export class HistoryService {
  private runs: MarkovianRun[] = [];
  private subscribers = new Set<() => void>();

  constructor(private persistence?: HistoryPersistence) {
    this.runs = persistence?.load() ?? [];
  }

  record(run: MarkovianRun): void {
    if (!run.chunkConfig)
      throw new Error(
        'Markovian: run records require a chunkConfig snapshot (AGENTS.md section 2.3)',
      );
    this.runs.push(run);
    this.persist();
    for (const fn of this.subscribers) fn();
  }

  list(): readonly MarkovianRun[] {
    return this.runs;
  }

  get(id: string): MarkovianRun | undefined {
    return this.runs.find((r) => r.id === id);
  }

  delete(id: string): void {
    this.runs = this.runs.filter((r) => r.id !== id);
    this.persist();
  }

  clear(): void {
    this.runs = [];
    this.persist();
  }

  subscribe(fn: () => void): () => void {
    this.subscribers.add(fn);
    return () => this.subscribers.delete(fn);
  }

  // Efficiency recomputed per run against ITS OWN snapshot, never a current config.
  cumulativeStats(): CumulativeStats {
    const stats: CumulativeStats = {
      totalRuns: this.runs.length,
      completedRuns: this.runs.filter((r) => r.status === 'completed').length,
      totalTokensUsed: 0,
      totalTokensSaved: 0,
      averageEfficiency: 0,
      totalChunksProcessed: 0,
      lastRunTimestamp: 0,
      efficiencyHistory: [],
    };
    for (const run of this.runs) {
      const eff = runEfficiency(run.chunks, run.chunkConfig);
      stats.totalTokensUsed += eff.totalTokensUsed;
      stats.totalTokensSaved += eff.tokensSaved;
      stats.totalChunksProcessed += run.chunks.length;
      stats.lastRunTimestamp = Math.max(stats.lastRunTimestamp, run.timestamp);
      stats.efficiencyHistory.push({
        timestamp: run.timestamp,
        efficiency: eff.efficiencyPercent,
        tokensSaved: eff.tokensSaved,
      });
    }
    if (this.runs.length) {
      stats.averageEfficiency =
        stats.efficiencyHistory.reduce((s, e) => s + e.efficiency, 0) / this.runs.length;
    }
    return stats;
  }

  // Actual per-step aggregation for the Engine tab (section 8.1 actual mode).
  performanceByStep(): { step: number; avgTokens: number; samples: number }[] {
    const buckets = new Map<number, { total: number; samples: number }>();
    for (const run of this.runs) {
      for (const c of run.chunks) {
        const b = buckets.get(c.id) ?? { total: 0, samples: 0 };
        b.total += c.tokens;
        b.samples += 1;
        buckets.set(c.id, b);
      }
    }
    return [...buckets.entries()]
      .sort((a, b) => a[0] - b[0])
      .map(([step, b]) => ({ step, avgTokens: b.total / b.samples, samples: b.samples }));
  }

  private persist(): void {
    this.persistence?.save(structuredClone(this.runs));
  }
}

=== markers ===
// Marker protocol (AGENTS.md section 3). Canonical markers are square-bracket:
// [STATE_CHECKPOINT] and [TASK_COMPLETE], with the listed backward-compatible
// variants. The angle-bracket forms (<CARRYOVER>, <DONE>, <PROGRESS>,
// <NEEDS_TOOL .../>) used across this engine's examples are accepted as
// additional detection aliases. Cleaning strips every form from display text.

export interface ParsedMarkers {
  state?: string; // text captured after/inside a state marker
  done: boolean; // final completion marker present
  progress?: string; // optional progress note
  needsTool?: { tool: string; input: string };
  needsClarification?: string;
  cleaned: string; // display-safe content, all markers stripped
}

const STATE_BLOCKS = [/<CARRYOVER>([\s\S]*?)<\/CARRYOVER>/g];
const STATE_TAILS = [
  /\[STATE_CHECKPOINT\]\s*([\s\S]*)$/,
  /@@@STATE@@@\s*([\s\S]*)$/,
  /(?<!_)\[STATE\]\s*([\s\S]*)$/,
  /---STATE---\s*([\s\S]*)$/,
];
const FINAL_MARKERS = [
  /\[TASK_COMPLETE\]/,
  /@@@FINAL@@@/,
  /(?<!_)\[FINAL\]/,
  /---FINAL---/,
  /<DONE\s*\/?>/,
];
const PROGRESS_BLOCK = /<PROGRESS>([\s\S]*?)<\/PROGRESS>/;
const NEEDS_TOOL = /[<[]NEEDS_TOOL\s+tool="([^"]+)"\s+input=(?:"([^"]*)"|'([^']*)')\s*\/?[\]>]/;
const NEEDS_CLARIFICATION = /[<[]NEEDS_CLARIFICATION[\]>]\s*([^\n]*)/;

export function parseMarkers(raw: string): ParsedMarkers {
  let state: string | undefined;
  let progress: string | undefined;
  let needsTool: ParsedMarkers['needsTool'];
  let needsClarification: string | undefined;

  for (const re of STATE_BLOCKS) {
    const matches = [...raw.matchAll(re)];
    if (matches.length) state = matches[matches.length - 1][1].trim();
  }
  if (state === undefined) {
    for (const re of STATE_TAILS) {
      const m = raw.match(re);
      if (m) {
        state = m[1].trim();
        break;
      }
    }
  }
  const done = FINAL_MARKERS.some((re) => re.test(raw));
  const p = raw.match(PROGRESS_BLOCK);
  if (p) progress = p[1].trim();
  const t = raw.match(NEEDS_TOOL);
  if (t) needsTool = { tool: t[1], input: t[2] ?? t[3] ?? '' };
  const c = raw.match(NEEDS_CLARIFICATION);
  if (c) needsClarification = c[1].trim();

  return { state, done, progress, needsTool, needsClarification, cleaned: cleanMarkers(raw) };
}

export function cleanMarkers(raw: string): string {
  let out = raw;
  out = out.replace(/<CARRYOVER>[\s\S]*?<\/CARRYOVER>/g, '');
  out = out.replace(/<PROGRESS>[\s\S]*?<\/PROGRESS>/g, '');
  out = out.replace(/[<[]NEEDS_TOOL[^\]>]*[\]>]/g, '');
  out = out.replace(/[<[]NEEDS_CLARIFICATION[\]>][^\n]*/g, '');
  out = out.replace(/\[STATE_CHECKPOINT\][\s\S]*$/, '');
  out = out.replace(/@@@STATE@@@[\s\S]*$/, '');
  out = out.replace(/---STATE---[\s\S]*$/, '');
  // bare [STATE] tail only when it starts a marker line, to avoid eating prose
  out = out.replace(/\n\[STATE\][\s\S]*$/, '');
  for (const re of [/\[TASK_COMPLETE\]/g, /@@@FINAL@@@/g, /---FINAL---/g, /<DONE\s*\/?>/g])
    out = out.replace(re, '');
  out = out.replace(/\n\[FINAL\][\s\S]*$/, '');
  return out
    .replace(/[ \t]+$/gm, '')
    .replace(/\n{3,}/g, '\n\n')
    .trim();
}

=== carryover ===
// State carryover service (AGENTS.md section 4.3). The compression cascade
// runs in strict order: marker override, LLM compression, heuristic
// extraction, tail truncation. Each level falls through on failure so the
// chain survives model/API instability.

import { estimateTokens } from './types';
import type { ChunkConfig } from './types';

export type CascadeLevel = 'marker' | 'llm' | 'heuristic' | 'truncation';

export interface CarryoverResult {
  carryover: string;
  level: CascadeLevel;
}

const KEY_PHRASE =
  /(?:^|\n|\.\s+)((?:Therefore|Key insight|Status|Decision|Decided|Next|Remaining|Completed)[^.\n]*)/gi;

export class CarryoverService {
  constructor(private compressorFn?: (prompt: string, systemPrompt: string) => Promise<string>) {}

  async next(args: {
    markerState: string | undefined;
    previousCarryover: string;
    chunkText: string;
    config: ChunkConfig;
  }): Promise<CarryoverResult> {
    const budget = args.config.carryoverTokens;

    // Level 1: explicit marker override. Accept iff >= 24 chars and within budget.
    if (args.markerState !== undefined) {
      const sanitized = args.markerState.replace(/[<>[\]@-]{3,}/g, '').trim();
      if (sanitized.length >= 24 && estimateTokens(sanitized) <= budget) {
        return { carryover: sanitized, level: 'marker' };
      }
    }

    // Level 2: LLM-based compression via the injected compressor.
    if (this.compressorFn) {
      try {
        const preview = args.chunkText.slice(-2000);
        const prompt =
          `Previous state:\n${args.previousCarryover || '(none)'}\n\nLatest chunk (tail):\n${preview}\n\n` +
          `Compress into 3-5 critical points as a labeled block:\nCOMPLETED: ...\nREMAINING: ...\nDECISIONS: ...\nCONTEXT: ...`;
        const compressed = (
          await this.compressorFn(
            prompt,
            'You compress reasoning state. Be terse and lossless on decisions.',
          )
        ).trim();
        if (compressed.length >= 24 && estimateTokens(compressed) <= budget) {
          return { carryover: compressed, level: 'llm' };
        }
      } catch {
        // fall through to heuristics
      }
    }

    // Level 3: heuristic key-phrase extraction.
    const phrases = [...args.chunkText.matchAll(KEY_PHRASE)].map((m) => m[1].trim()).slice(0, 5);
    if (phrases.length > 0) {
      const summary = phrases.join('; ');
      if (estimateTokens(summary) <= budget) return { carryover: summary, level: 'heuristic' };
    }

    // Level 4: absolute fallback, tail-truncate words to the token budget.
    const words = (args.chunkText || args.previousCarryover).split(/\s+/).filter(Boolean);
    let tail = '';
    for (let i = words.length - 1; i >= 0; i--) {
      const candidate = words[i] + (tail ? ' ' + tail : '');
      if (estimateTokens(candidate) > budget) break;
      tail = candidate;
    }
    return { carryover: tail, level: 'truncation' };
  }
}

export function canonicalBlock(parts: {
  completed: string;
  remaining: string;
  decisions: string;
  context: string;
}): string {
  return `COMPLETED: ${parts.completed}\nREMAINING: ${parts.remaining}\nDECISIONS: ${parts.decisions}\nCONTEXT: ${parts.context}`;
}

import { ChangeDetectionStrategy, Component, inject, signal } from '@angular/core';
import { AssistantService } from '../../services/assistant.service';

@Component({
  selector: 'app-assistant-panel',
  changeDetection: ChangeDetectionStrategy.OnPush,
  templateUrl: './assistant-panel.html',
  styleUrl: './assistant-panel.css',
})
export class AssistantPanel {
  protected readonly assistant = inject(AssistantService);
  protected readonly draft = signal('');

  protected onInput(event: Event): void {
    this.draft.set((event.target as HTMLInputElement).value);
  }

  protected send(input: HTMLInputElement): void {
    const text = this.draft();
    if (!text.trim()) {
      return;
    }

    this.draft.set('');
    input.value = '';
    void this.assistant.submit(text);
  }
}

