// World Model reference implementation facade. Event-sourced, deterministic,
// zero runtime dependencies. Single-writer discipline: every write goes
// through a FIFO queue per instance, so concurrent ingests serialize.

import {
  canonicalJson,
  contextIdFromAttrs,
  entityIdFromName,
  externalId,
  factId,
  relationshipId,
} from './stableIds';
import { decide, jaccard, nameSimilarity } from './resolve';
import { EventStore } from './store';
import { runIngestPipeline, worldStateShape } from './ingest';
import type {
  Context,
  Entity,
  Fact,
  IngestObservation,
  IngestReport,
  MergeProposal,
  Provenance,
  Relationship,
  StoredProvenance,
  WorldEvent,
  WorldModelOptions,
} from './types';

export * from './types';
export { canonicalJson, entityIdFromName, externalId, normalizeName, sha256Hex } from './stableIds';
export { levenshtein, nameSimilarity, decide, jaccard } from './resolve';
export { worldStateShape } from './ingest';

type ExternalKey = { system: string; id: string };

interface UpsertEntityInput {
  type: string;
  externalKey?: ExternalKey;
  name?: string;
  attrs?: Record<string, unknown>;
  source: Provenance;
  state?: Entity['state'];
}

interface UpsertContextInput {
  type: string;
  externalKey?: ExternalKey;
  attrs?: Record<string, unknown>;
  parent?: string;
  source: Provenance;
}

interface RelateInput {
  from: string;
  type: string;
  to: string;
  context?: string;
  attrs?: Record<string, unknown>;
  validFrom?: string;
  validTo?: string;
  source: Provenance;
}

interface AssertFactInput {
  about: string;
  predicate: string;
  value: unknown;
  confidence?: number;
  context?: string;
  source: Provenance;
}

interface CustomView<S> {
  events: string[];
  initialState: S;
  reducer: (state: S, event: WorldEvent) => S;
}

export class WorldModel {
  private store: EventStore;
  private opts: WorldModelOptions;
  private clock: () => Date;
  private writeLock: Promise<unknown> = Promise.resolve();
  private customViews = new Map<string, { spec: CustomView<unknown>; state: unknown }>();

  constructor(opts: WorldModelOptions) {
    if (!opts.namespace) throw new Error('WorldModel: namespace is required');
    this.opts = opts;
    this.clock = opts.clock ?? (() => new Date());
    this.store = new EventStore(
      opts.namespace,
      opts.storage ?? 'memory',
      opts.directory,
      opts.persistence,
    );
  }

  // ---------------------------------------------------------------- writes

  private enqueue<T>(fn: () => T | Promise<T>): Promise<T> {
    const next = this.writeLock.then(fn);
    this.writeLock = next.catch(() => undefined);
    return next;
  }

  private normalizeProvenance(source: Provenance | undefined): StoredProvenance {
    if (!source || !source.kind || source.at === undefined) {
      throw new Error(
        'World Model: every write carries provenance (kind + at). No provenance, no write.',
      );
    }
    const at = source.at instanceof Date ? source.at.toISOString() : source.at;
    return { ...source, at };
  }

  upsertEntity(input: UpsertEntityInput): Promise<Entity> {
    return this.enqueue(() => this.upsertEntityNow(input));
  }

  /** Synchronous variant for local-first UI stores that project immediately. */
  upsertEntitySync(input: UpsertEntityInput): Entity {
    return this.upsertEntityNow(input);
  }

  private upsertEntityNow(input: UpsertEntityInput): Entity {
    const source = this.normalizeProvenance(input.source);
    const name = input.name ?? (input.attrs?.['name'] as string | undefined);
    const id = input.externalKey
      ? externalId(input.type, input.externalKey.system, input.externalKey.id)
      : entityIdFromName(input.type, mustName(name));

    // Resolution pass for name-keyed entities: near-duplicates of the same
    // type either auto-merge (alias event) or queue for operator review.
    if (!input.externalKey && name) {
      for (const other of this.store.state.entities.values()) {
        if (other.type !== input.type || other.id === id || !other.name) continue;
        const similarity = nameSimilarity(name, other.name);
        const decision = decide(
          similarity,
          this.opts.resolver?.autoMergeAt ?? 0.85,
          this.opts.resolver?.reviewBand?.[0] ?? 0.82,
        );
        if (decision === 'auto-merge') {
          this.store.append(
            'alias',
            {
              aliasId: id,
              primaryId: other.id,
              mergedAt: source.at,
              mergedBy: 'resolver',
              reason: `similarity ${similarity.toFixed(3)}`,
            },
            source.at,
          );
          this.store.logAudit(
            'auto-merge',
            'resolver',
            `${name} -> ${other.name} (${similarity.toFixed(3)})`,
            undefined,
            undefined,
            source.at,
          );
          return this.foldEntityUpsert(other.id, input, source, name);
        }
        if (decision === 'review') {
          const proposalId = `merge_${this.store.mergeQueue.length + 1}`;
          if (
            !this.store.mergeQueue.some(
              (p) =>
                (p.leftId === id && p.rightId === other.id) ||
                (p.leftId === other.id && p.rightId === id),
            )
          ) {
            const proposal: MergeProposal = {
              id: proposalId,
              leftId: id,
              rightId: other.id,
              leftName: name,
              rightName: other.name,
              similarity,
              reason: 'name similarity in review band [0.82, 0.85)',
              status: 'pending',
              proposedAt: source.at,
            };
            this.store.mergeQueue.push(proposal);
            this.store.logAudit(
              'merge-proposed',
              'resolver',
              `${name} ~ ${other.name} (${similarity.toFixed(3)}) queued`,
              undefined,
              undefined,
              source.at,
            );
          }
        }
      }
    }
    return this.foldEntityUpsert(id, input, source, name);
  }

  private foldEntityUpsert(
    id: string,
    input: UpsertEntityInput,
    source: StoredProvenance,
    name?: string,
  ): Entity {
    const resolved = this.store.resolveAlias(id);
    const entity: Entity = {
      type: input.type,
      id: resolved,
      attrs: { ...(input.attrs ?? {}) },
      schemaVersion: 1,
      source,
      createdAt: source.at,
      updatedAt: source.at,
      name,
      aliases: name ? [name] : [],
      state: input.state ?? 'active',
    };
    const event = this.store.append('upsertEntity', entity, source.at);
    this.store.logAudit(
      'upsertEntity',
      source.by ?? 'system',
      `${resolved} (${input.type})`,
      event.id,
      source.runId,
      source.at,
    );
    return this.store.state.entities.get(resolved)!;
  }

  upsertContext(input: UpsertContextInput): Promise<Context> {
    return this.enqueue(() => {
      const source = this.normalizeProvenance(input.source);
      const id = input.externalKey
        ? externalId(input.type, input.externalKey.system, input.externalKey.id)
        : contextIdFromAttrs(input.type, input.attrs ?? {}, input.parent);
      const context: Context = {
        type: input.type,
        id,
        attrs: { ...(input.attrs ?? {}) },
        parent: input.parent,
        schemaVersion: 1,
        source,
        createdAt: source.at,
        updatedAt: source.at,
      };
      const event = this.store.append('upsertContext', context, source.at);
      this.store.logAudit(
        'upsertContext',
        source.by ?? 'system',
        `${id} (${input.type})`,
        event.id,
        source.runId,
        source.at,
      );
      return this.store.state.contexts.get(id)!;
    });
  }

  relate(input: RelateInput): Promise<Relationship> {
    return this.enqueue(() => {
      const source = this.normalizeProvenance(input.source);
      const from = this.store.resolveAlias(input.from);
      const to = this.store.resolveAlias(input.to);
      const id = relationshipId(from, input.type, to, input.context, input.validFrom);
      if (this.store.state.relationships.has(id)) {
        return this.store.state.relationships.get(id)!; // content-addressed no-op
      }
      const rel: Relationship = {
        id,
        from,
        type: input.type,
        to,
        context: input.context,
        attrs: input.attrs,
        validFrom: input.validFrom ?? source.at,
        validTo: input.validTo,
        schemaVersion: 1,
        source,
        createdAt: source.at,
      };
      const event = this.store.append('relate', rel, source.at);
      this.store.logAudit(
        'relate',
        source.by ?? 'system',
        `${from} -[${input.type}]-> ${to}`,
        event.id,
        source.runId,
        source.at,
      );
      return this.store.state.relationships.get(id)!;
    });
  }

  assertFact(input: AssertFactInput): Promise<Fact> {
    return this.enqueue(() => {
      const source = this.normalizeProvenance(input.source);
      const about = this.store.resolveAlias(input.about);
      const id = factId(about, input.predicate, input.value, source.at, source.kind, source.url);
      if (this.store.state.facts.has(id)) return this.store.state.facts.get(id)!;

      const fact: Fact = {
        id,
        about,
        predicate: input.predicate,
        value: input.value,
        confidence: input.confidence ?? 0.5,
        context: input.context,
        source,
        assertedAt: source.at,
      };

      // Conflict policy decides which fact's value lands on the entity.
      const policy = this.opts.conflictPolicy ?? 'most-recent-wins';
      const rivals = [...this.store.state.facts.values()].filter(
        (f) => f.about === about && f.predicate === input.predicate && !f.supersededBy,
      );
      let winner: Fact = fact;
      for (const rival of rivals) {
        const rivalWins =
          policy === 'highest-confidence-wins'
            ? rival.confidence > winner.confidence
            : policy === 'source-priority'
              ? priorityOf(rival.source.kind, this.opts.sourcePriority) <
                priorityOf(winner.source.kind, this.opts.sourcePriority)
              : rival.assertedAt > winner.assertedAt; // most-recent-wins
        if (rivalWins) {
          winner = rival;
        }
      }
      const event = this.store.append('assertFact', fact, source.at);
      for (const f of [fact, ...rivals]) {
        if (f.id !== winner.id) this.store.state.facts.get(f.id)!.supersededBy = winner.id;
      }

      // Ensure the subject entity exists and carries the winning value.
      if (!this.store.state.entities.get(about)) {
        const inferredType = about.includes(':') ? about.split(':')[0] : 'entity';
        this.store.append(
          'upsertEntity',
          {
            type: inferredType,
            id: about,
            attrs: {},
            schemaVersion: 1,
            source,
            createdAt: source.at,
            updatedAt: source.at,
            aliases: [],
            state: 'emerging',
          } as Entity,
          source.at,
        );
      }
      const entity = this.store.state.entities.get(about)!;
      entity.attrs[input.predicate] = winner.value;
      entity.updatedAt = source.at;

      this.store.logAudit(
        'assertFact',
        source.by ?? 'system',
        `${about}.${input.predicate} = ${JSON.stringify(winner.value)} (${policy})`,
        event.id,
        source.runId,
        source.at,
      );
      this.store.persist();
      return this.store.state.facts.get(id)!;
    });
  }

  tombstone(id: string, reason: string, source: Provenance): Promise<WorldEvent> {
    return this.enqueue(() => this.tombstoneNow(id, reason, source));
  }

  tombstoneSync(id: string, reason: string, source: Provenance): WorldEvent {
    return this.tombstoneNow(id, reason, source);
  }

  private tombstoneNow(id: string, reason: string, source: Provenance): WorldEvent {
    const normalized = this.normalizeProvenance(source);
    const targetId = this.store.resolveAlias(id);
    if (!this.store.state.entities.has(targetId)) {
      throw new Error(`World Model: unknown entity ${id}`);
    }
    const event = this.store.append(
      'tombstone',
      { targetId, reason, at: normalized.at, by: normalized.by },
      normalized.at,
    );
    this.store.logAudit(
      'tombstone',
      normalized.by ?? 'system',
      `${targetId} archived (${reason})`,
      event.id,
      normalized.runId,
      normalized.at,
    );
    return event;
  }

  // ---------------------------------------------------------------- ingest

  ingest(observations: IngestObservation[]): Promise<IngestReport> {
    return this.enqueue(() =>
      runIngestPipeline(
        this.store,
        observations,
        (obs) => {
          const source = this.normalizeProvenance({ ...obs.source, at: obs.at });
          const entity = this.foldEntityUpsert(
            externalId(obs.type ?? 'item', 'ingest', obs.externalId),
            {
              type: obs.type ?? 'item',
              externalKey: { system: 'ingest', id: obs.externalId },
              attrs: { title: obs.title, text: obs.text },
              source,
            },
            source,
            obs.title,
          );
          const entityIds: string[] = [];
          for (const mention of obs.entities ?? []) {
            const mid = entityIdFromName(mention.type, mention.name);
            this.foldEntityUpsert(
              mid,
              { type: mention.type, name: mention.name, source },
              source,
              mention.name,
            );
            entityIds.push(this.store.resolveAlias(mid));
            const rid = relationshipId(entity.id, 'mentions', this.store.resolveAlias(mid));
            if (!this.store.state.relationships.has(rid)) {
              this.store.append(
                'relate',
                {
                  id: rid,
                  from: entity.id,
                  type: 'mentions',
                  to: this.store.resolveAlias(mid),
                  validFrom: source.at,
                  schemaVersion: 1,
                  source,
                  createdAt: source.at,
                } as Relationship,
                source.at,
              );
            }
          }
          return { entityId: entity.id, entityIds: entityIds.sort() };
        },
        () => this.clock().getTime(),
      ),
    );
  }

  // ---------------------------------------------------------------- reads

  view(name: 'graph'): GraphView;
  view(name: 'facts'): FactsView;
  view(name: 'snapshot'): SnapshotView;
  view(name: 'timeline'): TimelineView;
  view(name: string): { get(): unknown };
  view(name: string): unknown {
    if (name === 'graph') return new GraphView(this.store);
    if (name === 'facts') return new FactsView(this.store);
    if (name === 'snapshot') return new SnapshotView(this.store);
    if (name === 'timeline') return new TimelineView(this.store);
    const custom = this.customViews.get(name);
    if (!custom) throw new Error(`World Model: unknown view "${name}"`);
    return {
      get: () => {
        let state = structuredClone(custom.spec.initialState);
        for (const e of this.store.events) {
          if (custom.spec.events.includes(e.kind)) state = custom.spec.reducer(state, e);
        }
        return state;
      },
    };
  }

  registerView<S>(name: string, spec: CustomView<S>): void {
    this.customViews.set(name, { spec: spec as CustomView<unknown>, state: spec.initialState });
  }

  // ------------------------------------------------------------- operator

  mergeQueue(): readonly MergeProposal[] {
    return this.store.mergeQueue;
  }

  approveMerge(proposalId: string, by: string): Promise<void> {
    return this.enqueue(() => {
      const p = this.store.mergeQueue.find((m) => m.id === proposalId && m.status === 'pending');
      if (!p) throw new Error(`World Model: no pending merge proposal ${proposalId}`);
      const at = this.clock().toISOString();
      p.status = 'approved';
      p.resolvedAt = at;
      p.resolvedBy = by;
      this.store.append(
        'alias',
        { aliasId: p.leftId, primaryId: p.rightId, mergedAt: at, mergedBy: by, reason: p.reason },
        at,
      );
      this.store.logAudit(
        'merge-approved',
        by,
        `${p.leftName} -> ${p.rightName}`,
        undefined,
        undefined,
        at,
      );
    });
  }

  rejectMerge(proposalId: string, by: string): Promise<void> {
    return this.enqueue(() => {
      const p = this.store.mergeQueue.find((m) => m.id === proposalId && m.status === 'pending');
      if (!p) throw new Error(`World Model: no pending merge proposal ${proposalId}`);
      p.status = 'rejected';
      p.resolvedAt = this.clock().toISOString();
      p.resolvedBy = by;
      this.store.logAudit('merge-rejected', by, `${p.leftName} stays separate from ${p.rightName}`);
      this.store.persist();
    });
  }

  audit(): readonly import('./types').AuditEntry[] {
    return this.store.audit;
  }

  events(): readonly WorldEvent[] {
    return this.store.events;
  }

  stateShape(): unknown {
    return worldStateShape(this.store);
  }

  stateShapeCanonical(): string {
    return canonicalJson(worldStateShape(this.store));
  }

  subscribeEvents(fn: (e: WorldEvent) => void): () => void {
    return this.store.subscribe(fn);
  }
}

// ------------------------------------------------------------------ views

class GraphView {
  constructor(private store: EventStore) {}

  entity(id: string): Entity | undefined {
    return this.store.state.entities.get(this.store.resolveAlias(id));
  }

  neighborsOf(id: string, opts?: { via?: string; inContext?: string; at?: string }): Entity[] {
    const rid = this.store.resolveAlias(id);
    const out: Entity[] = [];
    for (const rel of this.store.state.relationships.values()) {
      if (opts?.via && rel.type !== opts.via) continue;
      if (opts?.inContext && rel.context !== opts.inContext) continue;
      if (opts?.at && !validAt(rel, opts.at)) continue;
      if (!opts?.at && rel.validTo) continue; // closed edges excluded from "now" queries
      const other = rel.from === rid ? rel.to : rel.to === rid ? rel.from : undefined;
      if (!other) continue;
      const entity = this.store.state.entities.get(other);
      if (entity) out.push(entity);
    }
    return out.sort((a, b) => a.id.localeCompare(b.id));
  }

  incoming(id: string, opts?: { via?: string }): Entity[] {
    const rid = this.store.resolveAlias(id);
    const out: Entity[] = [];
    for (const rel of this.store.state.relationships.values()) {
      if (rel.to !== rid) continue;
      if (opts?.via && rel.type !== opts.via) continue;
      if (rel.validTo) continue;
      const entity = this.store.state.entities.get(rel.from);
      if (entity) out.push(entity);
    }
    return out.sort((a, b) => a.id.localeCompare(b.id));
  }

  entitiesInContext(contextId: string, opts?: { type?: string }): Entity[] {
    const seen = new Map<string, Entity>();
    for (const rel of this.store.state.relationships.values()) {
      if (rel.context !== contextId) continue;
      for (const id of [rel.from, rel.to]) {
        const entity = this.store.state.entities.get(id);
        if (entity && (!opts?.type || entity.type === opts.type)) seen.set(entity.id, entity);
      }
    }
    return [...seen.values()].sort((a, b) => a.id.localeCompare(b.id));
  }

  traverse(
    startId: string,
    opts: { via: string; direction: 'ancestors' | 'descendants'; maxDepth?: number },
  ): Entity[] {
    const maxDepth = opts.maxDepth ?? 5;
    const out: Entity[] = [];
    const visited = new Set<string>();
    let frontier = [this.store.resolveAlias(startId)];
    for (let depth = 0; depth < maxDepth && frontier.length; depth++) {
      const next: string[] = [];
      for (const id of frontier) {
        for (const rel of this.store.state.relationships.values()) {
          if (rel.type !== opts.via || rel.validTo) continue;
          const target =
            opts.direction === 'ancestors'
              ? rel.from === id
                ? rel.to
                : undefined
              : rel.to === id
                ? rel.from
                : undefined;
          if (target && !visited.has(target)) {
            visited.add(target);
            const entity = this.store.state.entities.get(target);
            if (entity) out.push(entity);
            next.push(target);
          }
        }
      }
      frontier = next;
    }
    return out;
  }

  query(opts: { type?: string; where?: (e: Entity) => boolean }): Entity[] {
    return [...this.store.state.entities.values()]
      .filter((e) => (!opts.type || e.type === opts.type) && (!opts.where || opts.where(e)))
      .sort((a, b) => a.id.localeCompare(b.id));
  }
}

class FactsView {
  constructor(private store: EventStore) {}
  about(id: string): Fact[] {
    const rid = this.store.resolveAlias(id);
    return [...this.store.state.facts.values()]
      .filter((f) => f.about === rid)
      .sort((a, b) => a.assertedAt.localeCompare(b.assertedAt));
  }
}

class SnapshotView {
  constructor(private store: EventStore) {}
  // Entity state as of a timestamp: replay events with at <= timestamp.
  entityAt(id: string, at: string): Entity | undefined {
    const iso = at.length === 10 ? `${at}T23:59:59.999Z` : at;
    const state = this.store.foldUntil(iso);
    let cur = id;
    const seen = new Set<string>();
    while (state.aliases.has(cur) && !seen.has(cur)) {
      seen.add(cur);
      cur = state.aliases.get(cur)!;
    }
    return state.entities.get(cur);
  }
}

class TimelineView {
  constructor(private store: EventStore) {}
  subscribe(fn: (e: WorldEvent) => void): () => void {
    return this.store.subscribe(fn);
  }
  get(): WorldEvent[] {
    return [...this.store.events];
  }
}

function validAt(rel: Relationship, at: string): boolean {
  if (rel.validFrom && at < rel.validFrom) return false;
  if (rel.validTo && at >= rel.validTo) return false;
  return true;
}

function priorityOf(kind: string, ranking?: string[]): number {
  const idx = (ranking ?? []).indexOf(kind);
  return idx === -1 ? Number.MAX_SAFE_INTEGER : idx;
}

function mustName(name: string | undefined): string {
  if (!name)
    throw new Error('World Model: name-keyed entities need a name (or provide an externalKey)');
  return name;
}

=== wm store ===
// Event-sourced canonical store. State is a fold over an append-only event
// log; views are projections of the fold. Persistence is a JSON file per
// namespace (.world/<namespace>.json) replayed on load. Every mutation writes
// an audit entry; the control plane reads the audit log.

import type {
  AuditEntry,
  Context,
  Entity,
  EventKind,
  Fact,
  Relationship,
  Snapshot,
  StoredProvenance,
  WorldEvent,
  MergeProposal,
  ObservationRecord,
  StoryAggregate,
  ScoreSnapshot,
  WorldPersistence,
  WorldSnapshot,
} from './types';

export interface FoldedState {
  entities: Map<string, Entity>;
  contexts: Map<string, Context>;
  relationships: Map<string, Relationship>;
  facts: Map<string, Fact>;
  aliases: Map<string, string>; // aliasId -> primaryId
}

export class EventStore {
  events: WorldEvent[] = [];
  audit: AuditEntry[] = [];
  observations = new Map<string, ObservationRecord>();
  stories = new Map<string, StoryAggregate>();
  scores: ScoreSnapshot[] = [];
  mergeQueue: MergeProposal[] = [];
  state: FoldedState = {
    entities: new Map(),
    contexts: new Map(),
    relationships: new Map(),
    facts: new Map(),
    aliases: new Map(),
  };
  private seq = 0;
  private auditSeq = 0;
  private readonly persistence?: WorldPersistence;
  private subscribers = new Set<(e: WorldEvent) => void>();

  constructor(
    namespace: string,
    storage: 'memory' | 'local',
    directory?: string,
    persistence?: WorldPersistence,
  ) {
    this.persistence = persistence;
    const saved = this.persistence?.load();
    if (saved) {
      this.audit = saved.audit ?? [];
      this.auditSeq = this.audit.length ? this.audit[this.audit.length - 1].seq : 0;
      this.observations = new Map(saved.observations ?? []);
      this.stories = new Map(saved.stories ?? []);
      this.scores = saved.scores ?? [];
      this.mergeQueue = saved.mergeQueue ?? [];
      for (const event of saved.events ?? []) this.applyAndRecord(event, false);
    }
  }

  append(kind: EventKind, payload: WorldEvent['payload'], at: string): WorldEvent {
    const event: WorldEvent = {
      id: `evt_${this.seq + 1}`,
      seq: this.seq + 1,
      kind,
      payload,
      schemaVersion: 1,
      at,
    };
    this.applyAndRecord(event, true);
    return event;
  }

  private applyAndRecord(event: WorldEvent, isNew: boolean): void {
    this.seq = Math.max(this.seq, event.seq);
    if (isNew) this.events.push(event);
    else this.events.push(event);
    this.fold(event);
    if (isNew) {
      this.persist();
      for (const fn of this.subscribers) fn(event);
    }
  }

  private fold(event: WorldEvent): void {
    switch (event.kind) {
      case 'upsertEntity': {
        const e = event.payload as Entity;
        const existing = this.state.entities.get(e.id);
        if (existing) {
          existing.attrs = { ...existing.attrs, ...e.attrs };
          existing.updatedAt = e.updatedAt;
          existing.source = e.source;
          if (e.name && !existing.aliases.includes(e.name)) existing.aliases.push(e.name);
          if (e.name) existing.name = e.name;
        } else {
          this.state.entities.set(e.id, structuredClone(e));
        }
        break;
      }
      case 'upsertContext': {
        const c = event.payload as Context;
        const existing = this.state.contexts.get(c.id);
        if (existing) {
          existing.attrs = { ...existing.attrs, ...c.attrs };
          existing.updatedAt = c.updatedAt;
        } else {
          this.state.contexts.set(c.id, structuredClone(c));
        }
        break;
      }
      case 'relate': {
        const r = event.payload as Relationship;
        // Superseding semantics: a new open edge with the same (from, type,
        // context) but different target CLOSES the previous open edge.
        for (const other of this.state.relationships.values()) {
          if (
            other.from === r.from &&
            other.type === r.type &&
            (other.context ?? '') === (r.context ?? '') &&
            other.to !== r.to &&
            !other.validTo &&
            !other.supersededBy
          ) {
            other.validTo = r.validFrom ?? r.createdAt;
            other.supersededBy = r.id;
          }
        }
        if (!this.state.relationships.has(r.id))
          this.state.relationships.set(r.id, structuredClone(r));
        break;
      }
      case 'assertFact': {
        const f = event.payload as Fact;
        if (!this.state.facts.has(f.id)) this.state.facts.set(f.id, structuredClone(f));
        break;
      }
      case 'alias': {
        const a = event.payload as { aliasId: string; primaryId: string };
        this.state.aliases.set(a.aliasId, a.primaryId);
        break;
      }
      case 'tombstone': {
        const t = event.payload as { targetId: string };
        const entity = this.state.entities.get(t.targetId);
        if (entity) {
          entity.state = 'archived';
          entity.updatedAt = event.at;
        }
        break;
      }
      case 'snapshot':
      case 'view-rebuild':
        break;
    }
  }

  // Replays the event log up to (and including) a timestamp: the snapshot view.
  foldUntil(at: string): FoldedState {
    const scratch = new EventStore('scratch', 'memory');
    for (const e of this.events) {
      if (e.at <= at) scratch.fold(e);
    }
    return scratch.state;
  }

  resolveAlias(id: string): string {
    let cur = id;
    const seen = new Set<string>();
    while (this.state.aliases.has(cur) && !seen.has(cur)) {
      seen.add(cur);
      cur = this.state.aliases.get(cur)!;
    }
    return cur;
  }

  logAudit(
    kind: string,
    actor: string,
    summary: string,
    eventId?: string,
    runId?: string,
    at?: string,
  ): void {
    this.audit.push({
      seq: ++this.auditSeq,
      at: at ?? new Date(0).toISOString(),
      kind,
      actor,
      summary,
      eventId,
      runId,
    });
    this.persist();
  }

  subscribe(fn: (e: WorldEvent) => void): () => void {
    this.subscribers.add(fn);
    return () => this.subscribers.delete(fn);
  }

  snapshotState(): WorldSnapshot {
    return {
      events: structuredClone(this.events),
      audit: structuredClone(this.audit),
      observations: structuredClone([...this.observations.entries()]),
      stories: structuredClone([...this.stories.entries()]),
      scores: structuredClone(this.scores),
      mergeQueue: structuredClone(this.mergeQueue),
    };
  }

  persist(): void {
    this.persistence?.save(this.snapshotState());
  }
}

// Canonical H-MEM shapes per AGENTS.md section 2 and 9.

export type MemoryType = 'personal' | 'factual' | 'preference' | 'general';
export type MemoryLayer = 'short_term' | 'working' | 'long_term';
export type ProvenanceOrigin =
  | 'chat_message'
  | 'user_correction'
  | 'file_save'
  | 'file_open'
  | 'file_edit'
  | 'model_response'
  | 'plan_completion'
  | 'document'
  | 'manual'
  | 'dream'
  | 'sleep_synthesis';

export interface Provenance {
  origin: ProvenanceOrigin;
  learnedAt: number;
  label: string;
  refs?: string[];
}

export interface MemoryRecord {
  id: string;
  content: string;
