// H-MEM reference implementation ported to a browser-safe core.
// Original implementation: Meterless H-MEM reference (Apache-2.0).
// Persistence is injected; the engine itself has no filesystem dependency.

import type {
  FeedbackKind,
  LedgerEntry,
  MemoryRecord,
  MiningEventType,
  QueryResult,
} from './types';
import type { AddInput } from './memoryStore';
import { MemoryStoreService } from './memoryStore';
import { TrustLedgerService } from './trustLedger';
import { MemoryMiningService } from './memoryMining';
import { MemoryRetrievalService } from './memoryRetrieval';
import { ConflictDetectionService } from './conflictDetection';
import { SleepCycleService } from './sleepCycle';
import { DreamingService } from './dreaming';

export * from './types';
export { MemoryStoreService } from './memoryStore';
export { TrustLedgerService } from './trustLedger';
export { MemoryMiningService, parseStrictJsonArray } from './memoryMining';
export { MemoryRetrievalService } from './memoryRetrieval';
export { ConflictDetectionService } from './conflictDetection';
export { SleepCycleService } from './sleepCycle';
export { DreamingService } from './dreaming';
export { embed, cosine, tokenize, jaccard } from './embeddings';

export interface HMEMSnapshot {
  store: { records: MemoryRecord[]; seq: number };
  ledger: LedgerEntry[];
}

export interface HMEMPersistence {
  load(): HMEMSnapshot | undefined;
  save(snapshot: HMEMSnapshot): void;
}

export interface HMEMRuntimeOptions {
  clock?: () => number;
  actor?: string;
  minerFn?: (prompt: string) => Promise<string>;
  persistence?: HMEMPersistence;
}

export class HMEM {
  readonly ledger: TrustLedgerService;
  readonly store: MemoryStoreService;
  readonly mining: MemoryMiningService;
  readonly retrieval: MemoryRetrievalService;
  readonly conflicts: ConflictDetectionService;
  readonly sleep: SleepCycleService;
  readonly dreaming: DreamingService;
  readonly clock: () => number;
  private readonly persistence?: HMEMPersistence;

  constructor(opts: HMEMRuntimeOptions = {}) {
    this.clock = opts.clock ?? Date.now;
    this.persistence = opts.persistence;
    const actor = opts.actor ?? 'system';
    this.ledger = new TrustLedgerService(this.clock, () => this.persist());
    this.store = new MemoryStoreService(this.clock, this.ledger, actor, () => this.persist());
    this.mining = new MemoryMiningService(this.store, this.clock, opts.minerFn);
    this.retrieval = new MemoryRetrievalService(this.store, this.ledger, this.clock, actor);
    this.conflicts = new ConflictDetectionService(this.store, this.ledger, this.clock, actor);
    this.sleep = new SleepCycleService(this.store, this.ledger, this.clock, actor);
    this.dreaming = new DreamingService(this.store, this.ledger, this.clock, actor);

    const saved = this.persistence?.load();
    if (saved) this.importState(saved);
  }

  add(input: AddInput): MemoryRecord {
    return this.store.add(input);
  }

  mine(event: MiningEventType, text: string, opts?: { chatId?: string }): Promise<MemoryRecord[]> {
    return this.mining.mineInteraction(event, text, opts);
  }

  query(query: string, opts?: { topN?: number; threshold?: number; chatId?: string }): QueryResult {
    return this.retrieval.query(query, opts);
  }

  feedback(memoryId: string, kind: FeedbackKind): void {
    this.retrieval.feedback(memoryId, kind);
  }

  exportState(): HMEMSnapshot {
    return {
      store: this.store.snapshotAll(),
      ledger: this.ledger.snapshot(),
    };
  }

  importState(snapshot: HMEMSnapshot): void {
    this.ledger.restoreAll(snapshot.ledger);
    this.store.restoreAll(snapshot.store.records, snapshot.store.seq);
  }

  private persist(): void {
    this.persistence?.save(this.exportState());
  }
}

=== memoryStore ===
// Tiered memory store with enrichment (AGENTS.md sections 2, 3, 5).
// A record with no source is rejected by construction. Enrichment runs on
// every add: domain classification, namespace, entity extraction (cap 10),
// relatedTo discovery (cap 5, bidirectional), supersedes detection.

import { DEFAULTS, clamp01 } from './types';
import type { MemoryLayer, MemoryRecord, MemoryType, Provenance } from './types';
import { cosine, embed, tokenize } from './embeddings';
import type { TrustLedgerService } from './trustLedger';

const TECH_TERMS = [
  'react',
  'python',
  'typescript',
  'javascript',
  'rust',
  'sqlite',
  'postgres',
  'indexeddb',
  'node',
  'docker',
  'graphql',
  'redis',
  'webrtc',
  'tauri',
  'electron',
  'llm',
  'embedding',
];
const DOMAIN_KEYWORDS: Record<string, string[]> = {
  tech: [
    'code',
    'bug',
    'api',
    'database',
    'deploy',
    'framework',
    'library',
    'server',
    ...TECH_TERMS,
  ],
  work: ['meeting', 'deadline', 'client', 'project', 'sprint', 'review', 'report'],
  personal: ['family', 'hobby', 'prefer', 'like', 'dislike', 'morning', 'evening'],
};

export interface AddInput {
  content: string;
  type?: MemoryType;
  layer?: MemoryLayer;
  tags?: string[];
  confidence?: number;
  source: string;
  provenance?: Provenance;
  chatId?: string;
  missionId?: string;
  goalRunId?: string;
  supersedes?: string;
  derivedFrom?: string[];
}

export class MemoryStoreService {
  private records = new Map<string, MemoryRecord>();
  private seq = 0;

  constructor(
    private clock: () => number,
    private ledger: TrustLedgerService,
    private actor: string,
    private onChange?: () => void,
  ) {}

  persist(): void {
    this.onChange?.();
  }

  add(input: AddInput): MemoryRecord {
    if (!input.source || input.source.trim() === '') {
      throw new Error(
        'H-MEM: a memory record with no source must be rejected by construction (AGENTS.md section 2)',
      );
    }
    const now = this.clock();
    const id = `mem-${++this.seq}`;
    const tags = [...(input.tags ?? [])];
    const domain = this.classifyDomain(input.content, tags, input.type ?? 'general');
    const record: MemoryRecord = {
      id,
      content: input.content,
      type: input.type ?? 'general',
      layer: input.layer ?? 'working',
      timestamp: now,
      lastAccessed: now,
      accessCount: 0,
      tags,
      embedding: embed(input.content),
      confidence: clamp01(input.confidence ?? 0.7),
      source: input.source,
      provenance: input.provenance ?? { origin: 'manual', learnedAt: now, label: input.source },
      chatId: input.chatId,
      missionId: input.missionId,
      goalRunId: input.goalRunId,
      domain,
      namespace: this.namespace(domain, input.type ?? 'general'),
      entities: this.extractEntities(input.content),
      relatedTo: [],
      supersedes: input.supersedes,
      derivedFrom: input.derivedFrom,
    };
    this.discoverRelationships(record);
    this.records.set(id, record);
    this.ledger.log(id, 'create', this.actor, { newState: snapshot(record) });
    this.persist();
    return record;
  }

  get(id: string): MemoryRecord | undefined {
    return this.records.get(id);
  }

  all(): MemoryRecord[] {
    return [...this.records.values()];
  }

  update(id: string, patch: Partial<MemoryRecord>): MemoryRecord {
    const rec = this.mustGet(id);
    const prev = snapshot(rec);
    Object.assign(rec, patch);
    this.ledger.log(id, 'update', this.actor, { previousState: prev, newState: snapshot(rec) });
    this.persist();
    return rec;
  }

  delete(id: string, reason: string): void {
    const rec = this.mustGet(id);
    this.records.delete(id);
    this.ledger.log(id, 'delete', this.actor, {
      previousState: snapshot(rec),
      details: { reason },
    });
    this.persist();
  }

  touch(id: string): void {
    const rec = this.mustGet(id);
    rec.lastAccessed = this.clock();
    rec.accessCount += 1;
  }

  promote(id: string, layer: MemoryLayer): void {
    const rec = this.mustGet(id);
    const prev = snapshot(rec);
    rec.layer = layer;
    this.ledger.log(id, 'promote', this.actor, { previousState: prev, newState: snapshot(rec) });
    this.persist();
  }

  restoreAll(records: MemoryRecord[], seq: number): void {
    this.records = new Map(records.map((r) => [r.id, structuredClone(r)]));
    this.seq = seq;
    this.persist();
  }

  snapshotAll(): { records: MemoryRecord[]; seq: number } {
    return { records: structuredClone([...this.records.values()]), seq: this.seq };
  }

  private mustGet(id: string): MemoryRecord {
    const rec = this.records.get(id);
    if (!rec) throw new Error(`H-MEM: unknown memory id ${id}`);
    return rec;
  }

  // Multi-pass domain classification (AGENTS.md section 5).
  classifyDomain(content: string, tags: string[], type: MemoryType): string {
    for (const t of tags) {
      if (t.startsWith('project:')) return t.slice('project:'.length);
      if (t.startsWith('tech:')) return 'tech';
    }
    const tokens = new Set(tokenize(content));
    let best = 'general';
    let bestScore = 0;
    for (const [domain, kws] of Object.entries(DOMAIN_KEYWORDS)) {
      let score = kws.reduce((s, kw) => s + (tokens.has(kw) ? 1 : 0), 0);
      if (domain === 'personal' && (type === 'personal' || type === 'preference')) score += 1;
      if (score > bestScore) {
        best = domain;
        bestScore = score;
      }
    }
    return bestScore > 0 ? best : 'general';
  }

  private namespace(domain: string, type: MemoryType): string {
    const bucket =
      type === 'preference' || type === 'personal'
        ? 'profile'
        : type === 'factual'
          ? 'facts'
          : 'notes';
    return `${domain}/${bucket}`;
  }

  extractEntities(content: string): string[] {
    const entities = new Set<string>();
    for (const t of tokenize(content)) if (TECH_TERMS.includes(t)) entities.add(t);
    for (const m of content.matchAll(/\b([A-Z][a-zA-Z]{2,})\b/g)) {
      const norm = m[1].toLowerCase();
      if (!['the', 'this', 'that', 'with'].includes(norm)) entities.add(norm);
    }
    return [...entities].slice(0, DEFAULTS.entityCap);
  }

  private discoverRelationships(record: MemoryRecord): void {
    const CORRECTION = /\b(actually|instead|no longer|not anymore|changed to|correction)\b/i;
    for (const other of this.records.values()) {
      if (record.relatedTo.length >= DEFAULTS.relatedCap) break;
      const sharedEntities = other.entities.filter((e) => record.entities.includes(e));
      const sim = cosine(record.embedding, other.embedding);
      if (!record.supersedes && sim > 0.85 && CORRECTION.test(record.content)) {
        record.supersedes = other.id;
        continue;
      }
      if (sharedEntities.length >= 1 && other.domain === record.domain) {
        record.relatedTo.push(other.id);
        if (other.relatedTo.length < DEFAULTS.relatedCap && !other.relatedTo.includes(record.id)) {
          other.relatedTo.push(record.id); // bidirectional link
        }
      }
    }
  }
}

export function snapshot(r: MemoryRecord): Partial<MemoryRecord> {
  const { embedding, ...rest } = structuredClone(r);
  return rest;
}

import { computed, effect, inject, Injectable, signal } from '@angular/core';
import { Task, TaskFilter } from '../models/task.model';
import { WorldModelService } from './world-model.service';

const STORAGE_KEY = 'angular-todo-app.tasks';

@Injectable({ providedIn: 'root' })
export class TaskStore {
  private readonly world = inject(WorldModelService);
  private readonly taskState = signal<Task[]>(this.load());
  private readonly filterState = signal<TaskFilter>('all');

  readonly tasks = this.taskState.asReadonly();
  readonly filter = this.filterState.asReadonly();

  readonly visibleTasks = computed(() => {
    const filter = this.filterState();

    return this.taskState().filter((task) => {
      if (filter === 'active') {
        return !task.completed;
      }

      if (filter === 'completed') {
        return task.completed;
      }

      return true;
    });
  });

  readonly remainingCount = computed(
    () => this.taskState().filter((task) => !task.completed).length,
  );

  readonly completedCount = computed(
    () => this.taskState().filter((task) => task.completed).length,
  );

  readonly counts = computed(() => ({
    all: this.taskState().length,
    active: this.remainingCount(),
    completed: this.completedCount(),
  }));

  constructor() {
    for (const task of this.taskState()) {
      this.world.upsertTask(task);
    }

    effect(() => this.save(this.taskState()));
  }

  add(title: string): void {
    const trimmed = title.trim();

    if (!trimmed) {
      return;
    }

    const task: Task = {
      id: this.createId(),
      title: trimmed,
      completed: false,
      createdAt: Date.now(),
    };

    this.taskState.update((tasks) => [...tasks, task]);
    this.world.upsertTask(task);
  }

  toggle(id: string): void {
    this.taskState.update((tasks) =>
      tasks.map((task) => (task.id === id ? { ...task, completed: !task.completed } : task)),
    );
    const updated = this.taskState().find((task) => task.id === id);
    if (updated) {
      this.world.upsertTask(updated);
    }
  }

  rename(id: string, title: string): void {
    const trimmed = title.trim();

    if (!trimmed) {
      return;
    }

    this.taskState.update((tasks) =>
      tasks.map((task) => (task.id === id ? { ...task, title: trimmed } : task)),
    );
    const updated = this.taskState().find((task) => task.id === id);
    if (updated) {
      this.world.upsertTask(updated);
    }
  }

  remove(id: string): void {
    const removed = this.taskState().find((task) => task.id === id);
    this.taskState.update((tasks) => tasks.filter((task) => task.id !== id));
    if (removed) {
      this.world.archiveTask(removed);
    }
  }

  setFilter(filter: TaskFilter): void {
    this.filterState.set(filter);
  }

  private createId(): string {
    return (
      globalThis.crypto?.randomUUID?.() ??
      `${Date.now().toString(36)}-${Math.random().toString(36).slice(2, 10)}`
    );
  }

  private load(): Task[] {
    try {
      const raw = globalThis.localStorage?.getItem(STORAGE_KEY);

      if (!raw) {
        return [];
      }

      const parsed: unknown = JSON.parse(raw);

      return Array.isArray(parsed) ? parsed.filter(isTask) : [];
    } catch {
      return [];
    }
  }

  private save(tasks: Task[]): void {
    try {
      globalThis.localStorage?.setItem(STORAGE_KEY, JSON.stringify(tasks));
    } catch {
      // Storage can be unavailable (private mode, quota). The app still works in memory.
    }
  }
}

function isTask(value: unknown): value is Task {
  if (typeof value !== 'object' || value === null) {
    return false;
  }

  const task = value as Partial<Task>;

  return (
    typeof task.id === 'string' &&
    typeof task.title === 'string' &&
    task.title.trim().length > 0 &&
    typeof task.completed === 'boolean' &&
    typeof task.createdAt === 'number'
  );
}

=== persistence ===
export function readJson<T>(key: string): T | undefined {
  try {
    const raw = globalThis.localStorage?.getItem(key);
    return raw ? (JSON.parse(raw) as T) : undefined;
  } catch {
    return undefined;
  }
}

export function writeJson(key: string, value: unknown): void {
  try {
    globalThis.localStorage?.setItem(key, JSON.stringify(value));
  } catch {
    // Storage can be unavailable (private mode, quota). Engines keep working in memory.
  }
}

import { computed, Injectable, signal } from '@angular/core';
import { externalId, WorldModel } from '../engines/world-model';
import type { AuditEntry, Entity, WorldEvent } from '../engines/world-model';
import type { Task } from '../models/task.model';
import { readJson, writeJson } from './persistence';

const WORLD_KEY = 'angular-todo-app.world.v1';

@Injectable({ providedIn: 'root' })
export class WorldModelService {
  private readonly revision = signal(0);
  private readonly world = new WorldModel({
    namespace: 'todo',
    storage: 'memory',
    persistence: {
      load: () => readJson(WORLD_KEY),
      save: (snapshot) => writeJson(WORLD_KEY, snapshot),
    },
  });

  readonly taskEntities = computed(() => {
    this.revision();
    return this.world
      .view('graph')
      .query({ type: 'task' })
      .filter((entity) => entity.state === 'active');
  });

  readonly recentEvents = computed<readonly WorldEvent[]>(() => {
    this.revision();
    return [...this.world.events()].slice(-6).reverse();
  });

  readonly recentAudit = computed<readonly AuditEntry[]>(() => {
    this.revision();
    return [...this.world.audit()].slice(-6).reverse();
  });

  readonly eventCount = computed(() => {
    this.revision();
    return this.world.events().length;
  });

  upsertTask(task: Task): void {
    const id = this.entityId(task.id);
    const existing = this.world.view('graph').entity(id);

    if (
      existing &&
      existing.state === 'active' &&
      existing.name === task.title &&
      existing.attrs['completed'] === task.completed
    ) {
      return;
    }

    this.world.upsertEntitySync({
      type: 'task',
      externalKey: { system: 'todo', id: task.id },
      name: task.title,
      attrs: {
        title: task.title,
        completed: task.completed,
        createdAt: task.createdAt,
      },
      source: { kind: 'user', by: 'local-user', at: new Date().toISOString() },
    });
    this.revision.update((value) => value + 1);
  }

  archiveTask(task: Task): void {
    try {
      this.world.tombstoneSync(this.entityId(task.id), 'task deleted', {
        kind: 'user',
        by: 'local-user',
        at: new Date().toISOString(),
      });
      this.revision.update((value) => value + 1);
    } catch {
      // The task may predate World Model persistence; nothing to archive.
    }
  }

  entityFor(task: Task): Entity | undefined {
    return this.world.view('graph').entity(this.entityId(task.id));
  }

  private entityId(taskId: string): string {
    return externalId('task', 'todo', taskId);
  }
}

