import { computed, Injectable, signal } from '@angular/core';
import { HMEM } from '../engines/hmem';
import type { HMEMSnapshot, MemoryRecord, QueryResult } from '../engines/hmem';
import { readJson, writeJson } from './persistence';

const MEMORY_KEY = 'angular-todo-app.hmem.v1';

@Injectable({ providedIn: 'root' })
export class MemoryService {
  private readonly revision = signal(0);
  private readonly hmem = new HMEM({
    actor: 'local-user',
    persistence: {
      load: () => readJson<HMEMSnapshot>(MEMORY_KEY),
      save: (snapshot) => writeJson(MEMORY_KEY, snapshot),
    },
  });

  readonly memories = computed<readonly MemoryRecord[]>(() => {
    this.revision();
    return this.hmem.store
      .all()
      .filter((memory) => !memory.supersededBy)
      .sort((left, right) => right.timestamp - left.timestamp);
  });

  readonly count = computed(() => this.memories().length);

  remember(content: string): MemoryRecord | undefined {
    const trimmed = content.trim();

    if (!trimmed) {
      return undefined;
    }

    const record = this.hmem.add({
      content: trimmed,
      type: /\b(prefer|like|love|hate|dislike)\b/i.test(trimmed) ? 'preference' : 'general',
      layer: 'long_term',
      tags: ['user', 'explicit'],
      confidence: 0.8,
      source: 'user',
    });
    this.revision.update((value) => value + 1);
    return record;
  }

  recall(query: string): QueryResult {
    const result = this.hmem.query(query, { threshold: 0.2, topN: 5 });
    this.hmem.store.persist();
    this.revision.update((value) => value + 1);
    return result;
  }

  forget(query: string): MemoryRecord | undefined {
    const result = this.recall(query);
    const target = result.memories[0]?.memory;

    if (!target) {
      return undefined;
    }

    this.hmem.store.delete(target.id, `user requested: ${query}`);
    this.revision.update((value) => value + 1);
    return target;
  }

  delete(id: string): void {
    this.hmem.store.delete(id, 'removed from memory panel');
    this.revision.update((value) => value + 1);
  }
}

import { inject, Injectable, signal } from '@angular/core';
import type { Decision } from '../engines/scout';
import type { Task } from '../models/task.model';
import { MemoryService } from './memory.service';
import { PlanningService } from './planning.service';
import { ScoutService } from './scout.service';
import { TaskStore } from './task-store';

export interface AssistantMessage {
  id: string;
  role: 'user' | 'assistant';
  text: string;
  meta?: string;
  tone?: 'normal' | 'success' | 'error';
}

export interface PendingAction {
  decision: Decision;
  label: string;
}

@Injectable({ providedIn: 'root' })
export class AssistantService {
  private readonly scout = inject(ScoutService);
  private readonly tasks = inject(TaskStore);
  private readonly memory = inject(MemoryService);
  private readonly planning = inject(PlanningService);

  readonly lastPlan = this.planning.lastPlan;
  readonly messages = signal<AssistantMessage[]>([]);
  readonly busy = signal(false);
  readonly pending = signal<PendingAction | null>(null);

  async submit(raw: string): Promise<void> {
    const text = raw.trim();

    if (!text || this.busy()) {
      return;
    }

    this.push('user', text);

    if (this.pending()) {
      if (/^(confirm|yes|do it|approve)\b/i.test(text)) {
        await this.confirm();
        return;
      }

      if (/^(cancel|no|stop)\b/i.test(text)) {
        this.cancel();
        return;
      }

      this.pending.set(null);
    }

    this.busy.set(true);

    try {
      const decision = await this.scout.decide(text);

      if (decision.clarification) {
        this.push('assistant', decision.clarification.question, this.meta(decision));
        return;
      }

      if (decision.risk.level === 'block') {
        this.push(
          'assistant',
          `I cannot run that request: ${decision.risk.reason ?? 'it was blocked by policy'}.`,
          this.meta(decision),
          'error',
        );
        return;
      }

      if (decision.risk.level === 'high') {
        this.pending.set({ decision, label: this.describe(decision) });
        this.push(
          'assistant',
          `This is a high-risk action: ${this.describe(decision)}. Confirm to proceed.`,
          this.meta(decision),
        );
        return;
      }

      await this.execute(decision);
    } catch (error) {
      this.push(
        'assistant',
        `Something went wrong: ${(error as Error).message}`,
        undefined,
        'error',
      );
    } finally {
      this.busy.set(false);
    }
  }

  async confirm(): Promise<void> {
    const pending = this.pending();

    if (!pending) {
      return;
    }

    this.pending.set(null);
    this.busy.set(true);

    try {
      await this.execute(pending.decision);
    } finally {
      this.busy.set(false);
    }
  }

  cancel(): void {
    this.pending.set(null);
    this.push('assistant', 'Cancelled. Nothing was changed.');
  }

  private async execute(decision: Decision): Promise<void> {
    const id = decision.intent.primary.id;
    const params = decision.intent.primary.parameters;
    const meta = this.meta(decision);

    switch (id) {
      case 'task.add': {
        const title = this.stringParam(params['title']);
        if (!title) {
          this.push('assistant', 'What should the task say?', meta);
          return;
        }
        this.tasks.add(title);
        this.push('assistant', `Added “${title}”.`, meta, 'success');
        return;
      }

      case 'task.complete':
      case 'task.uncomplete': {
        const task = this.findTask(this.stringParam(params['task']));
        if (!task) {
          this.push('assistant', 'I could not find that task. Try naming it more precisely.', meta);
          return;
        }
        const shouldComplete = id === 'task.complete';
        if (task.completed !== shouldComplete) {
          this.tasks.toggle(task.id);
        }
        this.push(
          'assistant',
          `${shouldComplete ? 'Completed' : 'Reopened'} “${task.title}”.`,
          meta,
          'success',
        );
        return;
      }

      case 'task.delete': {
        const scope = this.stringParam(params['scope']);
        if (scope === 'all' || scope === 'completed') {
          const targets =
            scope === 'all'
              ? [...this.tasks.tasks()]
              : this.tasks.tasks().filter((task) => task.completed);
          for (const task of targets) {
            this.tasks.remove(task.id);
          }
          this.push(
            'assistant',
            `Deleted ${targets.length} ${targets.length === 1 ? 'task' : 'tasks'} (${scope}).`,
            meta,
            'success',
          );
          return;
        }

        const task = this.findTask(this.stringParam(params['task']));
        if (!task) {
          this.push('assistant', 'I could not find that task to delete.', meta);
          return;
        }
        this.tasks.remove(task.id);
        this.push('assistant', `Deleted “${task.title}”.`, meta, 'success');
        return;
      }

      case 'task.rename': {
        const task = this.findTask(this.stringParam(params['task']));
        const title = this.stringParam(params['title']);
        if (!task || !title) {
          this.push('assistant', 'Tell me which task to rename and the new title.', meta);
          return;
        }
        this.tasks.rename(task.id, title);
        this.push('assistant', `Renamed “${task.title}” to “${title}”.`, meta, 'success');
        return;
      }

      case 'task.list': {
        const list = this.tasks.tasks();
        if (list.length === 0) {
          this.push('assistant', 'Your list is empty.', meta);
          return;
        }
        const lines = list.map((task) => `${task.completed ? '✓' : '○'} ${task.title}`);
        this.push('assistant', lines.join('\n'), meta);
        return;
      }

      case 'task.filter': {
        const filter = this.stringParam(params['filter']);
        if (filter !== 'active' && filter !== 'completed' && filter !== 'all') {
          this.push('assistant', 'Show all, active, or completed tasks?', meta);
          return;
        }
        this.tasks.setFilter(filter);
        this.push('assistant', `Showing ${filter} tasks.`, meta, 'success');
        return;
      }

      case 'task.summary': {
        const counts = this.tasks.counts();
        this.push(
          'assistant',
          `${counts.all} total · ${counts.active} active · ${counts.completed} completed.`,
          meta,
        );
        return;
      }

      case 'task.plan': {
        const goal = this.stringParam(params['goal']) ?? decision.prompt;
        const run = await this.planning.plan(goal);
        this.push(
          'assistant',
          run.output,
          `${meta} · Markovian ${run.id} · ${run.efficiencyPercent}% efficient`,
          'success',
        );
        return;
      }

      case 'memory.remember': {
        const content = this.stringParam(params['content']);
        if (!content) {
          this.push('assistant', 'What should I remember?', meta);
          return;
        }
        this.memory.remember(content);
        this.push('assistant', `Remembered: ${content}`, meta, 'success');
        return;
      }

      case 'memory.recall': {
        const result = this.memory.recall(this.stringParam(params['query']) ?? decision.prompt);
        if (result.memories.length > 0) {
          const lines = result.memories.map(
            ({ memory, relevance }) =>
              `• ${memory.content} (${Math.round(relevance * 100)}% relevant)`,
          );
          this.push('assistant', lines.join('\n'), meta);
          return;
        }

        const recent = this.memory.memories().slice(0, 5);
        if (recent.length === 0) {
          this.push('assistant', 'I do not have a relevant memory yet.', meta);
          return;
        }

        this.push(
          'assistant',
          [
            'No strong match, so here is what I remember:',
            ...recent.map((item) => `• ${item.content}`),
          ].join('\n'),
          meta,
        );
        return;
      }

      case 'memory.forget': {
        const query = this.stringParam(params['query']);
        const removed = query ? this.memory.forget(query) : undefined;
        this.push(
          'assistant',
          removed ? `Forgot: ${removed.content}` : 'I could not find a memory to forget.',
          meta,
          removed ? 'success' : 'normal',
        );
        return;
      }

      default:
        this.push(
          'assistant',
          'I can add, complete, reopen, rename, delete, filter, and summarize tasks; plan a goal; and remember or recall notes.',
          meta,
        );
    }
  }

  private findTask(query: string | undefined): Task | undefined {
    const normalized = (query ?? '')
      .toLowerCase()
      .replace(/\b(task|to-?do)\b/g, '')
      .replace(/\s+/g, ' ')
      .trim();

    if (!normalized) {
      return undefined;
    }

    const tasks = this.tasks.tasks();
    return (
      tasks.find((task) => task.title.toLowerCase() === normalized) ??
      tasks.find((task) => task.title.toLowerCase().includes(normalized)) ??
      tasks.find((task) => normalized.includes(task.title.toLowerCase()))
    );
  }

  private describe(decision: Decision): string {
    const id = decision.intent.primary.id;

    if (id === 'task.delete') {
      const scope = this.stringParam(decision.intent.primary.parameters['scope']);
      if (scope === 'all') return 'delete every task';
      if (scope === 'completed') return 'delete all completed tasks';
      return `delete “${this.stringParam(decision.intent.primary.parameters['task']) ?? 'the task'}”`;
    }

    return id.replace('.', ' ');
  }

  private meta(decision: Decision): string {
    return `Scout → ${decision.intent.primary.id} · ${Math.round(
      decision.intent.primary.confidence * 100,
    )}% · ${decision.risk.level} risk`;
  }

  private stringParam(value: unknown): string | undefined {
    return typeof value === 'string' && value.trim().length > 0 ? value.trim() : undefined;
  }

  private push(
    role: AssistantMessage['role'],
    text: string,
    meta?: string,
    tone: AssistantMessage['tone'] = 'normal',
  ): void {
    this.messages.update((messages) => [
      ...messages,
      {
        id: globalThis.crypto?.randomUUID?.() ?? `${Date.now()}-${Math.random()}`,
        role,
        text,
        meta,
        tone,
      },
    ]);
  }
}

=== swarm world ===
# Swarm planning with World context

> Cross-engine example: it runs once the swarm-orchestration spec and its reference implementation are published. Until then treat the code as a reference sketch of the contract.

An [Agent Orchestration](https://github.com/meterless/meterless/blob/main/ROADMAP.md) planner reads current world state **before** producing a DAG. Tasks are scoped to entities that actually exist, so the planner cannot hallucinate accounts that are not in the world. When the swarm finishes, its verified output flows back into the world as new facts.

> This is the World Model side of the `swarm-with-world-model` example in the [swarm-orchestration spec (next on the roadmap; link goes to the roadmap)](https://github.com/meterless/meterless/blob/main/ROADMAP.md). That example reads the world *from inside the swarm*; this one focuses on what the world exposes for grounded planning.

## What it shows

- A Swarm planner reading the World Model before DAG construction
- Per-task context injection from the World Model
- Swarm output flowing **back** into the World Model as new facts (closed loop)

Prerequisite reading: [`docs/read-surface.md`](../../docs/read-surface.md), [`examples/crm-account-world`](../crm-account-world/README.md). Composition reference: World Model how-to §13 (Swarm).

---

## The loop

```text
World Model ──(current accounts)──▶ Swarm planner ──▶ DAG of grounded tasks
     ▲                                                        │
     └────────────(verified outputs as facts)─────────────────┘
```

The world is **read-mostly during a run**, then written once at the end through the normal ingest pipeline. There is no privileged write path.

## Walkthrough

```ts
import { WorldModel } from "@meterless/world-model";
import { Swarm } from "@meterless/swarm";

const world = new WorldModel({ storage: "local", namespace: "swarm-demo" });
const swarm = new Swarm();

// The world already knows two accounts (from the CRM example).
const accounts = await world.view("graph").entitiesOfType("account");
console.log("accounts in world:", accounts.map((a) => a.attrs.name));

// 1. The planner reads world state, then builds a DAG scoped to REAL accounts.
const dag = await swarm.plan({
  goal: "Draft a Q3 renewal outreach for every active account",
  // The planner is handed the world; it cannot invent accounts.
  grounding: accounts.map((a) => ({ id: a.id, name: a.attrs.name })),
});

// 2. Each task gets per-task context injected from the World Model.
swarm.onTaskStart(async (task) => {
  const ctx = await world.buildPromptContext({ subjectId: task.subjectId, limit: 30 });
  task.augmentPrompt(ctx.text);
});

const result = await swarm.run(dag);

// 3. Verified swarm outputs flow BACK into the world as facts, through the same ingest path.
//    assertFact is the canonical write primitive for this.
for (const out of result.outputs) {
  await world.assertFact({
    about: out.subjectId,                       // e.g. "account:salesforce:0015g00000ACME"
    predicate: "outreach-draft",
    value: { draft: out.text, status: "ready-for-review" },
    confidence: 0.9,
    source: { kind: "agent", by: `swarm:${result.runId}`, at: new Date() },
    assertedAt: new Date(),
  });
}

const drafts = await world.facts({
  about: "account:salesforce:0015g00000ACME",
  predicate: "outreach-draft",
});
console.log("drafts attached to Acme:", drafts.length);
```

## Run it

This repo is an implementation spec. `@meterless/world-model` and `@meterless/swarm` name your implementations; neither is a published package. Treat `index.ts` as a reference program against the two contracts: point the imports at your own implementations (World Model per [`AGENTS.md`](../../AGENTS.md); Swarm per [https://github.com/meterless/meterless/blob/main/ROADMAP.md](https://github.com/meterless/meterless/blob/main/ROADMAP.md)), then run `npx tsx ./index.ts`.

## Expected output

```text
accounts in world: ["Acme Corp", "Globex"]
drafts attached to Acme: 1
```

The planner produced exactly two outreach tasks, one per real account. No phantom "MegaCorp" task, because the planner was grounded in the world, not free-associating. Each draft is written back as a provenanced fact.

---

## Why it matters

- **Grounded planning.** Handing the planner the actual account list is the difference between "draft outreach for Acme and Globex" and a DAG that invents a customer that does not exist. The world is the guardrail.
- **Per-task context.** Each task pulls only its subject's neighborhood (limit 30). Tasks stay focused and cheap; the planner does not stuff the entire world into every prompt.
- **The loop closes through the front door.** Swarm outputs re-enter via `assertFact`, the same idempotent, provenanced pipeline every other writer uses. A re-run of the swarm does not duplicate drafts (stable fact IDs); an operator can audit `source: swarm:<runId>`.
- **Read-mostly during the run.** The world is stable while the DAG executes; the single write burst at the end keeps the run reproducible and the audit trail clean.

## Next

- The `swarm-with-world-model` example in the [swarm-orchestration spec (next on the roadmap; link goes to the roadmap)](https://github.com/meterless/meterless/blob/main/ROADMAP.md): the reciprocal, the same integration from inside the swarm.
- [`scout-context-plan-to-world-query`](../scout-context-plan-to-world-query/README.md): Scout choosing the planner's grounding scope.
- [`crm-account-world`](../crm-account-world/README.md): the account world this planner reads from.
- [`docs/operator-control-plane.md`](../../docs/operator-control-plane.md): reviewing the `ready-for-review` drafts the swarm produced.

=== markovian inside swarm ===
# Markovian inside Swarm

> **Marker note:** this walkthrough uses the XML alternate (`<CARRYOVER>`, `<DONE>`) of the canonical bracket protocol (`[STATE_CHECKPOINT]` / `[TASK_COMPLETE]`). See [docs/marker-protocol.md](../../docs/marker-protocol.md) for the 1:1 mapping.

An agent orchestration task that runs a Markovian chain for its long-horizon reasoning. Swarm sees one task, and Markovian handles the chunking inside it. The two governance layers nest without overlap.

> This is the same integration as the `swarm-with-markovian` example planned for the swarm orchestration spec, seen from the Markovian side. The swarm-orchestration and runtime specs are next on the [roadmap](../../../../ROADMAP.md).

Prerequisite reading: [`docs/compose-with-swarm.md`](../../docs/compose-with-swarm.md), [`long-research-chain`](../long-research-chain/README.md).

---

## The boundary

```text
DAG level     planner ─▶ [architect task] ─▶ merge ─▶ verify
                              │  estimatedTokens > 4000
                              ▼
Task level             Markovian: chunk 1 → 2 → … → joined output
                              │
                              ▼
                       ONE artifact handed back to the scheduler
```

The scheduler governs *tasks* (readiness, concurrency, retries). Markovian governs *context within a task* (bounded chunks). Neither reaches into the other.

## Walkthrough: `index.ts`

```ts
import { Markovian } from "@meterless/markovian";

const markovian = new Markovian({
  chunkConfig: { chunkSize: 8000, carryoverTokens: 1200 },
});

// The ONLY place the two engines touch: inside a Swarm TaskRunner.
async function execute(task /*: SwarmTask */) {
  if (task.estimatedTokens > 4000) {
    const run = await markovian.run({
      goal: task.prompt,
      mode: task.role === "researcher" ? "RESEARCH" : "ARCHITECT",
      memoryContext: task.run.settings.memoryContext,   // H-MEM context, if any
      stepFn: defaultStepFn,
      stopWhen: ({ output }) => output.includes("<DONE>"),
    });

    // Contract: return ONE joined artifact; record the Markovian run id for audit.
    task.telemetry.emit("markovian_delegated", {
      taskId: task.id, markovianRunId: run.id, chunks: run.chunks.length,
    });
    return run.chunks.map((c) => c.content).join("\n\n");
  }

  return await yourLLM(task.prompt);   // small task → one shot, no Markovian
}
```

## Run it

```bash
# No npm package is published. This repo is an implementation spec.
# Point the import at your implementation of the engine contract (see ../../AGENTS.md), then:
npx tsx ./index.ts
```

## Expected behavior

```text
swarm DAG:  planner → architect_task → merge → verify
architect_task.estimatedTokens = 12,000  (> 4000) → delegate to Markovian
  markovian: 6 chunks, bounded carryover, <DONE> at chunk 6
  → returns ONE artifact to the scheduler
swarm telemetry: { kind: "markovian_delegated", taskId: "architect_task",
                   markovianRunId: "mk_91", chunks: 6 }
DAG view: architect_task = 1 task, 1 attempt, 1 artifact  (chunking invisible to the DAG)
```

## Contract at both boundaries

| Boundary | Contract |
| --- | --- |
| Swarm → Markovian | task prompt in; bounded chunks run internally |
| Markovian → Swarm | one joined artifact out; `markovianRunId` in telemetry |
| Audit | the Swarm run telemetry links to the inner Markovian run id for end-to-end reconstruction |

A small task (`≤ 4000` tokens) skips Markovian entirely. Delegation has a cost, so it only happens where the task is large enough to need it.

---

## Why it matters

- **The scheduler stays simple.** It never reasons about token windows; it governs tasks. Pushing bounded-context concerns down into the task keeps the DAG layer small and correct. Markovian pushes history concerns down into carryover for the same reason.
- **One artifact, one contract.** Markovian's N chunks become a single task artifact before merge/verify/resume ever see it. The orchestrator needs no special cases.
- **Two nested governances, both auditable.** Swarm bounds how many agents run and how they connect. Markovian bounds how much context one agent reasons over at once. The `markovianRunId` link stitches the two audit trails into one.

## Next

- [`markovian-with-hmem`](../markovian-with-hmem/README.md): the memory composition seam.
- Swarm side of this integration: the `swarm-with-markovian` example, planned for the swarm orchestration spec. That spec and the runtime spec are next on the [roadmap](../../../../ROADMAP.md).

=== crm account ===
# CRM account world

> Run it: `npx tsx index.ts` (uses the reference implementation in [`../../reference`](../../reference)).

Replace your CRM schema with a World Model. Accounts, contacts, threads, and deals all become entities, contexts, and relationships. The CRM "workflow" becomes a set of queries over derived views, and a custom projection replaces the dashboard.

## What it shows

- Accounts and contacts as entities (Salesforce external keys)
- Threads (email, Slack, calls) as **contexts**
- Deals as **relationships** scoped to a campaign context
- A **custom "stuck deals" projection**, the kind of view a CRM ships as a hard-coded report

Prerequisite reading: [`docs/entity-context-relationship-model.md`](../../docs/entity-context-relationship-model.md), [`docs/read-surface.md`](../../docs/read-surface.md).

---

## Scenario

Two accounts, their contacts, deals in flight, and last-touch threads:

```text
account:acme   ── employs ──▶ contact:jane@acme.com
account:globex ── employs ──▶ contact:raj@globex.com

deal (Acme · $80k · stage=negotiation · last touch 31d ago)   ← stuck
deal (Globex · $40k · stage=proposal  · last touch  3d ago)
```

## Walkthrough

```ts
import { WorldModel } from "@meterless/world-model";

const world = new WorldModel({ storage: "local", namespace: "crm" });

// Accounts + contacts: stable IDs pinned to the Salesforce external key.
for (const acc of [
  { sf: "0015g00000ACME", name: "Acme Corp" },
  { sf: "0015g00000GLBX", name: "Globex" },
]) {
  await world.upsertEntity({
    type: "account",
    externalKey: { system: "salesforce", id: acc.sf },
    attrs: { name: acc.name },
    source: { kind: "api", at: new Date() },
  });
}

for (const c of [
  { email: "jane@acme.com", name: "Jane Doe", acc: "0015g00000ACME" },
  { email: "raj@globex.com", name: "Raj Patel", acc: "0015g00000GLBX" },
]) {
  await world.upsertEntity({
    type: "contact",
    externalKey: { system: "email", id: c.email },
    attrs: { name: c.name },
    source: { kind: "api", at: new Date() },
  });
  await world.relate({
    from: `account:salesforce:${c.acc}`,
    type: "employs",
    to: `contact:email:${c.email}`,
    source: { kind: "api", at: new Date() },
  });
}

// A campaign context scopes the deals.
await world.upsertContext({
  type: "campaign",
  externalKey: { system: "internal", id: "q2-expansion" },
  attrs: { name: "Q2 Expansion" },
  source: { kind: "manual", at: new Date() },
});

// Deals as relationships scoped to the campaign, with stage + last-touch facts.
const now = Date.now();
const DAY = 86_400_000;
await world.relate({
  from: "account:salesforce:0015g00000ACME", type: "has-deal", to: "campaign:internal:q2-expansion",
  attrs: { amount: 80_000, stage: "negotiation", lastTouchAt: now - 31 * DAY },
  source: { kind: "api", at: new Date() },
});
await world.relate({
  from: "account:salesforce:0015g00000GLBX", type: "has-deal", to: "campaign:internal:q2-expansion",
  attrs: { amount: 40_000, stage: "proposal", lastTouchAt: now - 3 * DAY },
  source: { kind: "api", at: new Date() },
});

// "Stuck deals": a custom projection. This is the CRM report, as a view.
world.registerView("stuck-deals", {
  events: ["relate"],
  initialState: [] as Array<{ account: string; amount: number; idleDays: number }>,
  reducer: (state, event) => {
    if (event.kind === "relate" && event.payload.type === "has-deal") {
      const idleDays = (Date.now() - event.payload.attrs.lastTouchAt) / 86_400_000;
      if (idleDays > 14 && event.payload.attrs.stage !== "closed") {
        state.push({ account: event.payload.from, amount: event.payload.attrs.amount, idleDays: Math.round(idleDays) });
      }
    }
    return state;
  },
});

console.log(await world.view("stuck-deals").get());
```

## Run it

This repo is an implementation spec. `@meterless/world-model` is the name of your implementation, not a published package. Treat `index.ts` as a reference program against the contract in [`/docs`](../../docs/architecture.md): point the import at your own implementation (built per [`AGENTS.md`](../../AGENTS.md)), then run `npx tsx ./index.ts`.

## Expected output

```text
[{ account: "account:salesforce:0015g00000ACME", amount: 80000, idleDays: 31 }]
```

The Acme deal (31 idle days, still negotiating) is flagged. The Globex deal (3 days) is not.

---

## Why it matters

- **The CRM schema is just entity types.** Accounts, contacts, threads, and deals are declared types, not a database you had to design. Add `renewal` next quarter without a migration ceremony.
- **Reports are views, not tables.** "Stuck deals" is a projection over the event log. Change the rule (14 → 21 days) and re-derive; you never wrote a reporting table that can drift from the source of truth.
- **External keys make sync lossless.** Pinning the Salesforce ID means re-importing the same account is a no-op, and every system that knows that account agrees on its World Model ID.
- **Provenance answers the audit question CRMs cannot.** "Why does this deal show negotiation?" → the `relate` event's `source` block, six months later.

