// H-MEM reference implementation ported to a browser-safe core.
// Original implementation: Meterless H-MEM reference (Apache-2.0).
// Persistence is injected; the engine itself has no filesystem dependency.

import type {
  FeedbackKind,
  LedgerEntry,
  MemoryRecord,
  MiningEventType,
  QueryResult,
} from './types';
import type { AddInput } from './memoryStore';
import { MemoryStoreService } from './memoryStore';
import { TrustLedgerService } from './trustLedger';
import { MemoryMiningService } from './memoryMining';
import { MemoryRetrievalService } from './memoryRetrieval';
import { ConflictDetectionService } from './conflictDetection';
import { SleepCycleService } from './sleepCycle';
import { DreamingService } from './dreaming';

export * from './types';
export { MemoryStoreService } from './memoryStore';
export { TrustLedgerService } from './trustLedger';
export { MemoryMiningService, parseStrictJsonArray } from './memoryMining';
export { MemoryRetrievalService } from './memoryRetrieval';
export { ConflictDetectionService } from './conflictDetection';
export { SleepCycleService } from './sleepCycle';
export { DreamingService } from './dreaming';
export { embed, cosine, tokenize, jaccard } from './embeddings';

export interface HMEMSnapshot {
  store: { records: MemoryRecord[]; seq: number };
  ledger: LedgerEntry[];
}

export interface HMEMPersistence {
  load(): HMEMSnapshot | undefined;
  save(snapshot: HMEMSnapshot): void;
}

export interface HMEMRuntimeOptions {
  clock?: () => number;
  actor?: string;
  minerFn?: (prompt: string) => Promise<string>;
  persistence?: HMEMPersistence;
}

export class HMEM {
  readonly ledger: TrustLedgerService;
  readonly store: MemoryStoreService;
  readonly mining: MemoryMiningService;
  readonly retrieval: MemoryRetrievalService;
  readonly conflicts: ConflictDetectionService;
  readonly sleep: SleepCycleService;
  readonly dreaming: DreamingService;
  readonly clock: () => number;
  private readonly persistence?: HMEMPersistence;

  constructor(opts: HMEMRuntimeOptions = {}) {
    this.clock = opts.clock ?? Date.now;
    this.persistence = opts.persistence;
    const actor = opts.actor ?? 'system';
    this.ledger = new TrustLedgerService(this.clock, () => this.persist());
    this.store = new MemoryStoreService(this.clock, this.ledger, actor, () => this.persist());
    this.mining = new MemoryMiningService(this.store, this.clock, opts.minerFn);
    this.retrieval = new MemoryRetrievalService(this.store, this.ledger, this.clock, actor);
    this.conflicts = new ConflictDetectionService(this.store, this.ledger, this.clock, actor);
    this.sleep = new SleepCycleService(this.store, this.ledger, this.clock, actor);
    this.dreaming = new DreamingService(this.store, this.ledger, this.clock, actor);

    const saved = this.persistence?.load();
    if (saved) this.importState(saved);
  }

  add(input: AddInput): MemoryRecord {
    return this.store.add(input);
  }

  mine(event: MiningEventType, text: string, opts?: { chatId?: string }): Promise<MemoryRecord[]> {
    return this.mining.mineInteraction(event, text, opts);
  }

  query(query: string, opts?: { topN?: number; threshold?: number; chatId?: string }): QueryResult {
    return this.retrieval.query(query, opts);
  }

  feedback(memoryId: string, kind: FeedbackKind): void {
    this.retrieval.feedback(memoryId, kind);
  }

  exportState(): HMEMSnapshot {
    return {
      store: this.store.snapshotAll(),
      ledger: this.ledger.snapshot(),
    };
  }

  importState(snapshot: HMEMSnapshot): void {
    this.ledger.restoreAll(snapshot.ledger);
    this.store.restoreAll(snapshot.store.records, snapshot.store.seq);
  }

  private persist(): void {
    this.persistence?.save(this.exportState());
  }
}

=== retrieval ===
// Hybrid retrieval and reinjection (AGENTS.md section 6). The canonical formula:
//
//   raw = 0.35*semantic + 0.20*keyword + 0.10*tag + 0.10*domain
//       + 0.15*entity   + 0.05*layer   + 0.05*recency - 0.20*superseded
//   score = clamp01(raw) * confidence          <- confidence multiplies AFTER the sum
//
// keyword = Jaccard of the top-8 query tokens vs memory tokens.
// layer weights: long_term 1.0, working 0.8, short_term 0.6.
// recency = exponential decay on lastAccessed, 14-day time constant.
// superseded records are penalized, never deleted or filtered.
// Threshold 0.35 applies to the FINAL score; top N = 5.

import { DAY_MS, DEFAULTS, clamp01 } from './types';
import type { MemoryRecord, QueryResult, RetrievedMemory } from './types';
import { cosine, embed, jaccard, tokenize } from './embeddings';
import type { MemoryStoreService } from './memoryStore';
import type { TrustLedgerService } from './trustLedger';
import { FEEDBACK_DELTAS } from './types';
import type { FeedbackKind } from './types';
import { snapshot } from './memoryStore';

const LAYER_WEIGHT: Record<MemoryRecord['layer'], number> = {
  long_term: 1.0,
  working: 0.8,
  short_term: 0.6,
};

export class MemoryRetrievalService {
  constructor(
    private store: MemoryStoreService,
    private ledger: TrustLedgerService,
    private clock: () => number,
    private actor: string,
  ) {}

  scoreOne(memory: MemoryRecord, query: string): number {
    const queryEmbedding = embed(query);
    const queryTokens = tokenize(query).slice(0, 8);
    const queryEntities = this.store.extractEntities(query);
    const queryDomain = this.store.classifyDomain(query, [], 'general');
    return this.score(memory, queryEmbedding, queryTokens, queryEntities, queryDomain);
  }

  private score(
    m: MemoryRecord,
    queryEmbedding: number[],
    queryTokens: string[],
    queryEntities: string[],
    queryDomain: string,
  ): number {
    const semantic = clamp01(cosine(queryEmbedding, m.embedding));
    const keyword = jaccard(queryTokens, tokenize(m.content));
    const tag = jaccard(
      queryTokens,
      m.tags.map((t) => t.toLowerCase()),
    );
    const domain = m.domain === queryDomain ? 1 : 0;
    const entity = jaccard(queryEntities, m.entities);
    const layer = LAYER_WEIGHT[m.layer];
    const ageDays = (this.clock() - m.lastAccessed) / DAY_MS;
    const recency = Math.exp(-ageDays / DEFAULTS.recencyDays);
    const superseded = m.supersededBy ? 1 : 0;
    const raw =
      0.35 * semantic +
      0.2 * keyword +
      0.1 * tag +
      0.1 * domain +
      0.15 * entity +
      0.05 * layer +
      0.05 * recency -
      0.2 * superseded;
    return clamp01(raw) * m.confidence;
  }

  query(query: string, opts?: { topN?: number; threshold?: number; chatId?: string }): QueryResult {
    const queryEmbedding = embed(query);
    const queryTokens = tokenize(query).slice(0, 8);
    const queryEntities = this.store.extractEntities(query);
    const queryDomain = this.store.classifyDomain(query, [], 'general');
    const threshold = opts?.threshold ?? DEFAULTS.retrievalThreshold;
    const topN = opts?.topN ?? DEFAULTS.retrievalTopN;

    const scored: RetrievedMemory[] = [];
    for (const m of this.store.all()) {
      if (opts?.chatId && m.chatId && m.chatId !== opts.chatId) continue;
      const s = this.score(m, queryEmbedding, queryTokens, queryEntities, queryDomain);
      if (s >= threshold) scored.push({ memory: m, relevance: s });
    }
    scored.sort((a, b) => b.relevance - a.relevance || a.memory.id.localeCompare(b.memory.id));
    const top = scored.slice(0, topN);

    for (const { memory } of top) {
      this.store.touch(memory.id);
      this.ledger.log(memory.id, 'read', this.actor, { details: { query } });
    }

    const strategy =
      top.length <= 1
        ? 'minimal'
        : top.some((t) => t.memory.type === 'personal' || t.memory.type === 'preference')
          ? 'personal'
          : 'comprehensive';
    return {
      memories: top,
      context: this.formatReinjection(top),
      trace: {
        retrievalReason: `hybrid ranking for "${query}" (domain: ${queryDomain})`,
        strategy,
        scores: Object.fromEntries(top.map((t) => [t.memory.id, Number(t.relevance.toFixed(4))])),
      },
    };
  }

  // Domain-grouped reinjection blocks with layer markers and entities (section 6.2).
  formatReinjection(items: RetrievedMemory[]): string {
    if (items.length === 0) return '';
    const byDomain = new Map<string, RetrievedMemory[]>();
    for (const it of items) {
      const list = byDomain.get(it.memory.domain) ?? [];
      list.push(it);
      byDomain.set(it.memory.domain, list);
    }
    const lines: string[] = ['[MEMORY CONTEXT]'];
    for (const [domain, list] of [...byDomain.entries()].sort()) {
      lines.push(`## ${domain}`);
      for (const { memory } of list) {
        const marker =
          memory.layer === 'long_term' ? 'LT' : memory.layer === 'working' ? 'WK' : 'ST';
        const ents = memory.entities.length ? ` (entities: ${memory.entities.join(', ')})` : '';
        lines.push(`- [${marker}] ${memory.content}${ents} <${memory.id}>`);
      }
    }
    lines.push('[/MEMORY CONTEXT]');
    return lines.join('\n');
  }

  // Exact feedback deltas (AGENTS.md section 9.2).
  feedback(memoryId: string, kind: FeedbackKind): void {
    const m = this.store.get(memoryId);
    if (!m) throw new Error(`H-MEM: unknown memory id ${memoryId}`);
    const prev = snapshot(m);
    if (kind === 'helpful') m.accessCount += 1;
    m.confidence = clamp01(m.confidence + FEEDBACK_DELTAS[kind]);
    if (kind === 'wrong' && !m.tags.includes('review')) m.tags.push('review');
    this.ledger.log(memoryId, 'feedback', this.actor, {
      previousState: prev,
      newState: snapshot(m),
      details: { kind, delta: FEEDBACK_DELTAS[kind] },
    });
    this.store.persist();
  }
}

// World Model reference implementation facade. Event-sourced, deterministic,
// zero runtime dependencies. Single-writer discipline: every write goes
// through a FIFO queue per instance, so concurrent ingests serialize.

import {
  canonicalJson,
  contextIdFromAttrs,
  entityIdFromName,
  externalId,
  factId,
  relationshipId,
} from './stableIds';
import { decide, jaccard, nameSimilarity } from './resolve';
import { EventStore } from './store';
import { runIngestPipeline, worldStateShape } from './ingest';
import type {
  Context,
  Entity,
  Fact,
  IngestObservation,
  IngestReport,
  MergeProposal,
  Provenance,
  Relationship,
  StoredProvenance,
  WorldEvent,
  WorldModelOptions,
} from './types';

export * from './types';
export { canonicalJson, entityIdFromName, externalId, normalizeName, sha256Hex } from './stableIds';
export { levenshtein, nameSimilarity, decide, jaccard } from './resolve';
export { worldStateShape } from './ingest';

type ExternalKey = { system: string; id: string };

interface UpsertEntityInput {
  type: string;
  externalKey?: ExternalKey;
  name?: string;
  attrs?: Record<string, unknown>;
  source: Provenance;
  state?: Entity['state'];
}

interface UpsertContextInput {
  type: string;
  externalKey?: ExternalKey;
  attrs?: Record<string, unknown>;
  parent?: string;
  source: Provenance;
}

interface RelateInput {
  from: string;
  type: string;
  to: string;
  context?: string;
  attrs?: Record<string, unknown>;
  validFrom?: string;
  validTo?: string;
  source: Provenance;
}

interface AssertFactInput {
  about: string;
  predicate: string;
  value: unknown;
  confidence?: number;
  context?: string;
  source: Provenance;
}

interface CustomView<S> {
  events: string[];
  initialState: S;
  reducer: (state: S, event: WorldEvent) => S;
}

export class WorldModel {
  private store: EventStore;
  private opts: WorldModelOptions;
  private clock: () => Date;
  private writeLock: Promise<unknown> = Promise.resolve();
  private customViews = new Map<string, { spec: CustomView<unknown>; state: unknown }>();

  constructor(opts: WorldModelOptions) {
    if (!opts.namespace) throw new Error('WorldModel: namespace is required');
    this.opts = opts;
    this.clock = opts.clock ?? (() => new Date());
    this.store = new EventStore(
      opts.namespace,
      opts.storage ?? 'memory',
      opts.directory,
      opts.persistence,
    );
  }

  // ---------------------------------------------------------------- writes

  private enqueue<T>(fn: () => T | Promise<T>): Promise<T> {
    const next = this.writeLock.then(fn);
    this.writeLock = next.catch(() => undefined);
    return next;
  }

  private normalizeProvenance(source: Provenance | undefined): StoredProvenance {
    if (!source || !source.kind || source.at === undefined) {
      throw new Error(
        'World Model: every write carries provenance (kind + at). No provenance, no write.',
      );
    }
    const at = source.at instanceof Date ? source.at.toISOString() : source.at;
    return { ...source, at };
  }

  upsertEntity(input: UpsertEntityInput): Promise<Entity> {
    return this.enqueue(() => this.upsertEntityNow(input));
  }

  /** Synchronous variant for local-first UI stores that project immediately. */
  upsertEntitySync(input: UpsertEntityInput): Entity {
    return this.upsertEntityNow(input);
  }

  private upsertEntityNow(input: UpsertEntityInput): Entity {
    const source = this.normalizeProvenance(input.source);
    const name = input.name ?? (input.attrs?.['name'] as string | undefined);
    const id = input.externalKey
      ? externalId(input.type, input.externalKey.system, input.externalKey.id)
      : entityIdFromName(input.type, mustName(name));

    // Resolution pass for name-keyed entities: near-duplicates of the same
    // type either auto-merge (alias event) or queue for operator review.
    if (!input.externalKey && name) {
      for (const other of this.store.state.entities.values()) {
        if (other.type !== input.type || other.id === id || !other.name) continue;
        const similarity = nameSimilarity(name, other.name);
        const decision = decide(
          similarity,
          this.opts.resolver?.autoMergeAt ?? 0.85,
          this.opts.resolver?.reviewBand?.[0] ?? 0.82,
        );
        if (decision === 'auto-merge') {
          this.store.append(
            'alias',
            {
              aliasId: id,
              primaryId: other.id,
              mergedAt: source.at,
              mergedBy: 'resolver',
              reason: `similarity ${similarity.toFixed(3)}`,
            },
            source.at,
          );
          this.store.logAudit(
            'auto-merge',
            'resolver',
            `${name} -> ${other.name} (${similarity.toFixed(3)})`,
            undefined,
            undefined,
            source.at,
          );
          return this.foldEntityUpsert(other.id, input, source, name);
        }
        if (decision === 'review') {
          const proposalId = `merge_${this.store.mergeQueue.length + 1}`;
          if (
            !this.store.mergeQueue.some(
              (p) =>
                (p.leftId === id && p.rightId === other.id) ||
                (p.leftId === other.id && p.rightId === id),
            )
          ) {
            const proposal: MergeProposal = {
              id: proposalId,
              leftId: id,
              rightId: other.id,
              leftName: name,
              rightName: other.name,
              similarity,
              reason: 'name similarity in review band [0.82, 0.85)',
              status: 'pending',
              proposedAt: source.at,
            };
            this.store.mergeQueue.push(proposal);
            this.store.logAudit(
              'merge-proposed',
              'resolver',
              `${name} ~ ${other.name} (${similarity.toFixed(3)}) queued`,
              undefined,
              undefined,
              source.at,
            );
          }
        }
      }
    }
    return this.foldEntityUpsert(id, input, source, name);
  }

  private foldEntityUpsert(
    id: string,
    input: UpsertEntityInput,
    source: StoredProvenance,
    name?: string,
  ): Entity {
    const resolved = this.store.resolveAlias(id);
    const entity: Entity = {
      type: input.type,
      id: resolved,
      attrs: { ...(input.attrs ?? {}) },
      schemaVersion: 1,
      source,
      createdAt: source.at,
      updatedAt: source.at,
      name,
      aliases: name ? [name] : [],
      state: input.state ?? 'active',
    };
    const event = this.store.append('upsertEntity', entity, source.at);
    this.store.logAudit(
      'upsertEntity',
      source.by ?? 'system',
      `${resolved} (${input.type})`,
      event.id,
      source.runId,
      source.at,
    );
    return this.store.state.entities.get(resolved)!;
  }

  upsertContext(input: UpsertContextInput): Promise<Context> {
    return this.enqueue(() => {
      const source = this.normalizeProvenance(input.source);
      const id = input.externalKey
        ? externalId(input.type, input.externalKey.system, input.externalKey.id)
        : contextIdFromAttrs(input.type, input.attrs ?? {}, input.parent);
      const context: Context = {
        type: input.type,
122:  upsertEntitySync(input: UpsertEntityInput): Entity {
262:  relate(input: RelateInput): Promise<Relationship> {
284:      const event = this.store.append('relate', rel, source.at);
286:        'relate',
297:  assertFact(input: AssertFactInput): Promise<Fact> {
333:      const event = this.store.append('assertFact', fact, source.at);
362:        'assertFact',
378:  tombstoneSync(id: string, reason: string, source: Provenance): WorldEvent {
437:                'relate',
461:  view(name: 'graph'): GraphView;
462:  view(name: 'facts'): FactsView;
463:  view(name: 'snapshot'): SnapshotView;
464:  view(name: 'timeline'): TimelineView;
465:  view(name: string): { get(): unknown };
466:  view(name: string): unknown {

    this.store.logAudit(
      'upsertContext',
      source.by ?? 'system',
      `${id} (${input.type})`,
      event.id,
      source.runId,
      source.at,
    );
    return this.store.state.contexts.get(id)!;
  });
}

relate(input: RelateInput): Promise<Relationship> {
  return this.enqueue(() => {
    const source = this.normalizeProvenance(input.source);
    const from = this.store.resolveAlias(input.from);
    const to = this.store.resolveAlias(input.to);
    const id = relationshipId(from, input.type, to, input.context, input.validFrom);
    if (this.store.state.relationships.has(id)) {
      return this.store.state.relationships.get(id)!; // content-addressed no-op
    }
    const rel: Relationship = {
      id,
      from,
      type: input.type,
      to,
      context: input.context,
      attrs: input.attrs,
      validFrom: input.validFrom ?? source.at,
      validTo: input.validTo,
      schemaVersion: 1,
      source,
      createdAt: source.at,
    };
    const event = this.store.append('relate', rel, source.at);
    this.store.logAudit(
      'relate',
      source.by ?? 'system',
      `${from} -[${input.type}]-> ${to}`,
      event.id,
      source.runId,
      source.at,
    );
    return this.store.state.relationships.get(id)!;
  });
}

assertFact(input: AssertFactInput): Promise<Fact> {
  return this.enqueue(() => {
    const source = this.normalizeProvenance(input.source);
    const about = this.store.resolveAlias(input.about);
    const id = factId(about, input.predicate, input.value, source.at, source.kind, source.url);
    if (this.store.state.facts.has(id)) return this.store.state.facts.get(id)!;

    const fact: Fact = {
      id,
      about,
      predicate: input.predicate,
      value: input.value,
      confidence: input.confidence ?? 0.5,
      context: input.context,
      source,
      assertedAt: source.at,
    };

    // Conflict policy decides which fact's value lands on the entity.
    const policy = this.opts.conflictPolicy ?? 'most-recent-wins';
    const rivals = [...this.store.state.facts.values()].filter(
      (f) => f.about === about && f.predicate === input.predicate && !f.supersededBy,
    );
    let winner: Fact = fact;
    for (const rival of rivals) {
      const rivalWins =
        policy === 'highest-confidence-wins'
          ? rival.confidence > winner.confidence
          : policy === 'source-priority'
            ? priorityOf(rival.source.kind, this.opts.sourcePriority) <
              priorityOf(winner.source.kind, this.opts.sourcePriority)
            : rival.assertedAt > winner.assertedAt; // most-recent-wins
      if (rivalWins) {
        winner = rival;
      }
    }
    const event = this.store.append('assertFact', fact, source.at);
    for (const f of [fact, ...rivals]) {
      if (f.id !== winner.id) this.store.state.facts.get(f.id)!.supersededBy = winner.id;
    }

    // Ensure the subject entity exists and carries the winning value.
    if (!this.store.state.entities.get(about)) {
      const inferredType = about.includes(':') ? about.split(':')[0] : 'entity';
      this.store.append(
        'upsertEntity',
        {
          type: inferredType,
          id: about,
          attrs: {},
          schemaVersion: 1,
          source,
          createdAt: source.at,
          updatedAt: source.at,
          aliases: [],
          state: 'emerging',
        } as Entity,
        source.at,
      );
    }
    const entity = this.store.state.entities.get(about)!;
    entity.attrs[input.predicate] = winner.value;
    entity.updatedAt = source.at;

    this.store.logAudit(
      'assertFact',
      source.by ?? 'system',
      `${about}.${input.predicate} = ${JSON.stringify(winner.value)} (${policy})`,
      event.id,
      source.runId,
      source.at,
    );
    this.store.persist();
    return this.store.state.facts.get(id)!;
  });
}

tombstone(id: string, reason: string, source: Provenance): Promise<WorldEvent> {
  return this.enqueue(() => this.tombstoneNow(id, reason, source));
}

tombstoneSync(id: string, reason: string, source: Provenance): WorldEvent {
  return this.tombstoneNow(id, reason, source);
}

private tombstoneNow(id: string, reason: string, source: Provenance): WorldEvent {
  const normalized = this.normalizeProvenance(source);
  const targetId = this.store.resolveAlias(id);
  if (!this.store.state.entities.has(targetId)) {
    throw new Error(`World Model: unknown entity ${id}`);
  }
  const event = this.store.append(
    'tombstone',
    { targetId, reason, at: normalized.at, by: normalized.by },
    normalized.at,
  );
  this.store.logAudit(
    'tombstone',
    normalized.by ?? 'system',
    `${targetId} archived (${reason})`,
    event.id,
    normalized.runId,
    normalized.at,
  );

