// Markovian reference implementation facade. Deterministic, zero runtime
// dependencies. Implements AGENTS.md: config bounds and validation, marker
// protocol, compression cascade, mode prompts, orchestrator loop, progress,
// history with mandatory config snapshots, reflection, and the section 14
// accounting rules (chars/4 labeled "estimated"; [OVERLAP] implemented).

import { resolveConfig } from './configManager';
import { CarryoverService } from './carryover';
import { HistoryService } from './history';
import { orchestrate } from './orchestrator';
import { ProgressService } from './progress';
import type {
  ChunkConfig,
  Generator,
  MarkovianOptions,
  MarkovianRun,
  ProgressState,
  RunOptions,
} from './types';

export * from './types';
export {
  resolveConfig,
  projectionCurve,
  runEfficiency,
  modelTotals,
  DOC_DEFAULTS,
} from './configManager';
export { parseMarkers, cleanMarkers } from './markers';
export { CarryoverService, canonicalBlock } from './carryover';
export { buildPrompt, overlapSlice } from './promptBuilder';
export { ProgressService } from './progress';
export { HistoryService } from './history';
export { resetRunSeq } from './orchestrator';

export class Markovian {
  readonly config: ChunkConfig;
  readonly history: HistoryService;
  readonly progress: ProgressService;
  private carryoverService: CarryoverService;
  private clock: () => number;
  private defaultGenerator?: Generator;

  constructor(opts: MarkovianOptions = {}) {
    this.config = resolveConfig(opts.chunkConfig);
    this.clock = opts.clock ?? Date.now;
    this.history = new HistoryService(opts.persistence);
    this.progress = new ProgressService(this.clock, this.config.maxChunks);
    this.carryoverService = new CarryoverService(opts.compressorFn);
    this.defaultGenerator = opts.generator;
  }

  onProgress(fn: (s: ProgressState) => void): () => void {
    return this.progress.subscribe(fn);
  }

  async run(options: RunOptions): Promise<MarkovianRun> {
    const run = await orchestrate({
      options,
      config: this.config,
      clock: this.clock,
      progress: this.progress,
      carryoverService: this.carryoverService,
      defaultGenerator: this.defaultGenerator,
    });
    this.history.record(run);
    return run;
  }
}

import { inject, Injectable, signal } from '@angular/core';
import type { Decision } from '../engines/scout';
import type { Task } from '../models/task.model';
import { MemoryService } from './memory.service';
import { PlanningService } from './planning.service';
import { ScoutService } from './scout.service';
import { TaskStore } from './task-store';

export interface AssistantMessage {
  id: string;
  role: 'user' | 'assistant';
  text: string;
  meta?: string;
  tone?: 'normal' | 'success' | 'error';
}

export interface PendingAction {
  decision: Decision;
  label: string;
}

@Injectable({ providedIn: 'root' })
export class AssistantService {
  private readonly scout = inject(ScoutService);
  private readonly tasks = inject(TaskStore);
  private readonly memory = inject(MemoryService);
  private readonly planning = inject(PlanningService);

  readonly lastPlan = this.planning.lastPlan;
  readonly messages = signal<AssistantMessage[]>([]);
  readonly busy = signal(false);
  readonly pending = signal<PendingAction | null>(null);

  async submit(raw: string): Promise<void> {
    const text = raw.trim();

    if (!text || this.busy()) {
      return;
    }

    this.push('user', text);

    if (this.pending()) {
      if (/^(confirm|yes|do it|approve)\b/i.test(text)) {
        await this.confirm();
        return;
      }

      if (/^(cancel|no|stop)\b/i.test(text)) {
        this.cancel();
        return;
      }

      this.pending.set(null);
    }

    this.busy.set(true);

    try {
      const decision = await this.scout.decide(text);

      if (decision.clarification) {
        this.push('assistant', decision.clarification.question, this.meta(decision));
        return;
      }

      if (decision.risk.level === 'block') {
        this.push(
          'assistant',
          `I cannot run that request: ${decision.risk.reason ?? 'it was blocked by policy'}.`,
          this.meta(decision),
          'error',
        );
        return;
      }

      if (decision.risk.level === 'high') {
        this.pending.set({ decision, label: this.describe(decision) });
        this.push(
          'assistant',
          `This is a high-risk action: ${this.describe(decision)}. Confirm to proceed.`,
          this.meta(decision),
        );
        return;
      }

      await this.execute(decision);
    } catch (error) {
      this.push(
        'assistant',
        `Something went wrong: ${(error as Error).message}`,
        undefined,
        'error',
      );
    } finally {
      this.busy.set(false);
    }
  }

  async confirm(): Promise<void> {
    const pending = this.pending();

    if (!pending) {
      return;
    }

    this.pending.set(null);
    this.busy.set(true);

    try {
      await this.execute(pending.decision);
