import { ChangeDetectionStrategy, Component, output, signal } from '@angular/core';

@Component({
  selector: 'app-task-input',
  changeDetection: ChangeDetectionStrategy.OnPush,
  templateUrl: './task-input.html',
  styleUrl: './task-input.css',
})
export class TaskInput {
  readonly taskAdded = output<string>();
  protected readonly draft = signal('');

  protected onInput(event: Event): void {
    this.draft.set((event.target as HTMLInputElement).value);
  }

  protected addTask(input: HTMLInputElement): void {
    const title = this.draft().trim();

    if (!title) {
      return;
    }

    this.taskAdded.emit(title);
    this.draft.set('');
    input.value = '';
    input.focus();
  }
}
<form class="task-input" (submit)="$event.preventDefault(); addTask(input)">
  <label class="sr-only" for="new-task">New task</label>
  <input
    #input
    id="new-task"
    type="text"
    placeholder="What needs to be done?"
    autocomplete="off"
    [value]="draft()"
    (input)="onInput($event)"
  />
  <button type="submit" [disabled]="!draft().trim()">Add</button>
</form>
import { ChangeDetectionStrategy, Component, input, output } from '@angular/core';
import { TaskFilter } from '../../models/task.model';

interface FilterOption {
  value: TaskFilter;
  label: string;
}

@Component({
  selector: 'app-task-filters',
  changeDetection: ChangeDetectionStrategy.OnPush,
  templateUrl: './task-filters.html',
  styleUrl: './task-filters.css',
})
export class TaskFilters {
  readonly filter = input.required<TaskFilter>();
  readonly counts = input.required<Record<TaskFilter, number>>();
  readonly filterChange = output<TaskFilter>();

  protected readonly options: readonly FilterOption[] = [
    { value: 'all', label: 'All' },
    { value: 'active', label: 'Active' },
    { value: 'completed', label: 'Completed' },
  ];
}
<div class="filters" role="group" aria-label="Filter tasks">
  @for (option of options; track option.value) {
    <button
      type="button"
      [class.active]="filter() === option.value"
      [attr.aria-pressed]="filter() === option.value"
      (click)="filterChange.emit(option.value)"
    >
      {{ option.label }}
      <span class="count">{{ counts()[option.value] }}</span>
    </button>
  }
</div>

