import { ChangeDetectionStrategy, Component, inject, signal } from '@angular/core';
import { MemoryService } from '../../services/memory.service';

@Component({
  selector: 'app-memory-panel',
  changeDetection: ChangeDetectionStrategy.OnPush,
  templateUrl: './memory-panel.html',
  styleUrl: './memory-panel.css',
})
export class MemoryPanel {
  protected readonly memory = inject(MemoryService);
  protected readonly draft = signal('');

  protected onInput(event: Event): void {
    this.draft.set((event.target as HTMLInputElement).value);
  }

  protected remember(input: HTMLInputElement): void {
    const content = this.draft().trim();
    if (!content) {
      return;
    }

    this.memory.remember(content);
    this.draft.set('');
    input.value = '';
  }
}
<section class="panel" aria-labelledby="memory-title">
  <header class="panel-head">
    <div>
      <p class="eyebrow">H-MEM</p>
      <h2 id="memory-title">Memory</h2>
    </div>
    <span class="count">{{ memory.count() }}</span>
  </header>

  @if (memory.memories().length === 0) {
    <p class="hint">Nothing remembered yet. Add a preference or fact below.</p>
  } @else {
    <ul class="memory-list">
      @for (record of memory.memories().slice(0, 6); track record.id) {
        <li>
          <p>{{ record.content }}</p>
          <button
            type="button"
            [attr.aria-label]="'Forget ' + record.content"
            (click)="memory.delete(record.id)"
          >
            ×
          </button>
        </li>
      }
    </ul>
  }

  <form class="remember" (submit)="$event.preventDefault(); remember(input)">
    <label class="sr-only" for="memory-input">Remember a preference</label>
    <input
      #input
      id="memory-input"
      type="text"
      placeholder="Remember a preference or fact…"
      autocomplete="off"
      [value]="draft()"
