    const world = TestBed.inject(WorldModelService);
    world.upsertPlanDraft({ id: 'run-1', goal: 'week', runId: 'run-1', selected: false, output: 'A' });
    world.upsertPlanDraft({ id: 'run-2', goal: 'week', runId: 'run-2', selected: false, output: 'B' });
