const { chromium } = require('/home/ext_root/.local/share/mise/installs/npm-playwright/1.64.1/node_modules/playwright');
(async () => {
  const browser = await chromium.launch({ headless: true });
  try {
    const page = await browser.newPage();
    const logs = [];
    page.on('console', (m) => logs.push(m.type() + ': ' + m.text()));
    page.on('pageerror', (e) => logs.push('pageerror: ' + e));
    await page.goto('http://localhost:4200', { waitUntil: 'networkidle' });
    console.log('title', await page.title());
    console.log('h1', await page.locator('h1').allTextContents());
    const input = page.locator('#new-task');
    console.log('input count', await input.count());
    await input.fill('Ship the report');
    console.log('value', await input.inputValue());
    const button = page.locator('app-task-input button[type="submit"]');
    console.log('disabled', await button.isDisabled());
    await button.click();
    await page.waitForTimeout(1000);
    console.log('task items', await page.locator('app-task-item').count());
    console.log('body text', (await page.locator('body').innerText()).slice(0, 500));
    console.log('logs', logs);
  } finally {
    await browser.close();
