const assert = require('node:assert/strict');
const { chromium } = require('/home/ext_root/.local/share/mise/installs/npm-playwright/1.64.1/node_modules/playwright');

(async () => {
  const browser = await chromium.launch({ headless: true });
  try {
    const page = await browser.newPage();
    const consoleErrors = [];
    const pageErrors = [];
    const remoteRequests = [];
    page.on('console', (msg) => { if (msg.type() === 'error') consoleErrors.push(msg.text()); });
    page.on('pageerror', (err) => pageErrors.push(String(err)));
    page.on('request', (req) => {
      const url = req.url();
      if (!url.startsWith('http://localhost:4200') && !url.startsWith('data:')) remoteRequests.push(url);
    });

    await page.goto('http://localhost:4200', { waitUntil: 'networkidle' });
    await page.getByRole('heading', { name: 'Tasks' }).waitFor();

    const taskInput = page.locator('app-task-input #new-task');
    const taskItem = (title) => page.locator('li[app-task-item]').filter({ hasText: title });
    await taskInput.fill('Ship the report');
    await page.locator('app-task-input button[type="submit"]').click();
    await taskItem('Ship the report').waitFor();
    await page.locator('app-world-panel').getByText(/events/).waitFor();
    assert.ok((await page.locator('app-world-panel').textContent()).includes('active task entities'));

    const assistant = page.locator('app-assistant-panel');
    const assistantInput = assistant.locator('#assistant-input');
    const send = assistant.locator('button[type="submit"]');

    await assistantInput.fill('Remember that I prefer short answers');
    await send.click();
    await assistant.getByText('Remembered: I prefer short answers').waitFor();

    await assistantInput.fill('The usual');
    await send.click();
    await assistant.getByText(/From memory:/).waitFor();
    assert.ok((await assistant.textContent()).includes('short answers'));

    await assistantInput.fill('Plan my week');
    await send.click();
    await assistant.getByText(/Plan for my week/).waitFor();
    await page.locator('app-memory-panel').getByText(/Completed plan for/).waitFor();

    await assistantInput.fill('Plan my week');
    await send.click();
    await page.waitForFunction(() => {
      const nodes = Array.from(document.querySelectorAll('app-assistant-panel .message'));
      return nodes.filter((node) => node.textContent.includes('Plan for my week')).length >= 2;
    });

    const trace = page.locator('app-trace-panel');
    await trace.getByText('Context plan').click();
    for (const stage of ['context-plan', 'memory-recall', 'world-query', 'scout-decide', 'contract', 'execution', 'memory-write']) {
      assert.ok((await trace.textContent()).includes(stage), 'missing stage ' + stage);
    }
    await trace.getByText('Memory IDs').click();
    assert.ok((await trace.textContent()).includes('recalled') || (await trace.textContent()).includes('No memory recalled'));

    await taskItem('Ship the report').getByRole('button', { name: 'Delete task' }).click();
    await page.locator('app-memory-panel').getByText(/was archived/).waitFor();
    assert.equal(await taskItem('Ship the report').count(), 0);

    await taskInput.fill('Persist me');
    await page.locator('app-task-input button[type="submit"]').click();
    await taskItem('Persist me').waitFor();
    await page.reload({ waitUntil: 'networkidle' });
    await taskItem('Persist me').waitFor();
    assert.ok((await page.locator('app-memory-panel').textContent()).includes('Completed plan for'));
    assert.ok((await page.locator('app-memory-panel').textContent()).includes('was archived'));
    assert.ok((await page.locator('app-trace-panel').textContent()).includes('task.add'));

    assert.deepEqual(pageErrors, []);
    assert.deepEqual(consoleErrors, []);
    assert.deepEqual(remoteRequests, []);

    console.log('PASS browser smoke: add, world update, memory, vague reference, plans, trace, delete archive, refresh persistence, no console/page/network errors');
  } finally {
    await browser.close();
  }
})().catch((error) => { console.error(error); process.exit(1); });
