+
+  private contextualScore(prompt: string, intent: IntentDefinition, context: unknown): number {
+    const contextText = contextToString(context);
+    if (!contextText) {
+      return 0;
+    }
+
+    if (intent.id === 'task.compare' && /\b(compare|alternative|option)/i.test(prompt)) {
